{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app using AWS Secrets Manager for runtime secrets",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.600.0",
    "dotenv": "^16.4.5",
    "express": "^4.19.2"
  }
}

/**
 * secrets.js
 *
 * Centralised secret resolution with AWS Secrets Manager as the primary
 * source and a local .env.test fallback that is only active when
 * NODE_ENV=development.
 *
 * Design decisions
 * ────────────────
 * • .env.test is parsed **for key names only** at module load time so that
 *   the rest of the codebase never has to know which secrets exist.
 * • Secret values are fetched from AWS Secrets Manager on every getSecret()
 *   call (use an in-process cache if latency becomes a concern).
 * • The .env.test fallback is intentionally restricted to NODE_ENV=development
 *   so that misconfigured staging/production environments fail loudly instead
 *   of silently falling back to test credentials.
 * • No secret value is ever logged, exported as a module-level variable, or
 *   embedded in source code.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ── 1. Configuration ──────────────────────────────────────────────────────────

const ENV_FILE        = path.resolve(__dirname, '.env.test');
const IS_DEVELOPMENT  = process.env.NODE_ENV === 'development';

// AWS region is read from the environment; no default is assumed so that a
// missing region fails fast rather than silently hitting the wrong endpoint.
const smClient = new SecretsManagerClient({
  region: process.env.AWS_REGION,
});

// ── 2. Parse .env.test for key names (never store the values) ─────────────────

/**
 * Returns the set of secret names declared in the .env.test file.
 * Only non-empty, non-comment lines that contain an '=' are considered.
 *
 * @returns {Set<string>}
 */
function loadSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found – no secret names loaded.`);
    return new Set();
  }

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  const names = new Set();

  for (const raw of lines) {
    const line = raw.trim();
    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex < 1) continue;          // malformed – no key before '='

    const key = line.slice(0, eqIndex).trim();
    if (key) names.add(key);
  }

  return names;
}

/** Immutable set of secret names derived from .env.test. */
const SECRET_NAMES = loadSecretNames();

// ── 3. Development-only local fallback ───────────────────────────────────────

/**
 * Lazily-populated map of local values read from .env.test.
 * Only populated when NODE_ENV=development; null otherwise.
 *
 * We load this separately from SECRET_NAMES so that values are never
 * accidentally available in non-development builds.
 *
 * @type {Map<string, string> | null}
 */
let _localValues = null;

function getLocalValues() {
  if (!IS_DEVELOPMENT) return null;
  if (_localValues)    return _localValues;

  if (!fs.existsSync(ENV_FILE)) return null;

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');
  _localValues = new Map();

  for (const raw of lines) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex < 1) continue;

    const key   = line.slice(0, eqIndex).trim();
    const value = line.slice(eqIndex + 1).trim();

    if (key) _localValues.set(key, value);
  }

  return _localValues;
}

// ── 4. Primary resolver: AWS Secrets Manager ─────────────────────────────────

/**
 * Fetches a secret value from AWS Secrets Manager by name.
 *
 * AWS Secrets Manager supports two storage formats:
 *   • Plain string  – the entire SecretString is the value.
 *   • JSON object   – the SecretString is a JSON document; the value is
 *                     extracted using `name` as the JSON key.
 *
 * @param   {string}          name  The secret name as it appears in .env.test
 *                                  and in AWS Secrets Manager.
 * @returns {Promise<string>}       The resolved secret value.
 * @throws  {Error}                 If the secret cannot be resolved from any
 *                                  source and no fallback is available.
 */
async function fetchFromSecretsManager(name) {
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await smClient.send(command);

  const raw = response.SecretString;
  if (raw === undefined || raw === null) {
    throw new Error(`[secrets] Secret "${name}" has no SecretString value in Secrets Manager.`);
  }

  // Attempt JSON parse; if the document contains the key, return that field.
  // Otherwise treat the entire string as the secret value.
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null && Object.prototype.hasOwnProperty.call(parsed, name)) {
      return parsed[name];
    }
    // The JSON object exists but doesn't have a matching key – return raw JSON.
    return raw;
  } catch {
    // Not JSON – the raw string is the secret.
    return raw;
  }
}

// ── 5. Public API ─────────────────────────────────────────────────────────────

/**
 * Resolves a secret by name.
 *
 * Resolution order:
 *   1. AWS Secrets Manager (all environments).
 *   2. Local .env.test file  (development only, when Secrets Manager fails).
 *
 * @param   {string}          name  The secret name (must be present in .env.test).
 * @returns {Promise<string>}       The resolved secret value.
 * @throws  {Error}                 When the name is unknown or all sources fail.
 */
async function getSecret(name) {
  if (!SECRET_NAMES.has(name)) {
    throw new Error(
      `[secrets] Unknown secret "${name}". ` +
      `Add it to ${ENV_FILE} (key only, no value required in production).`
    );
  }

  try {
    return await fetchFromSecretsManager(name);
  } catch (smError) {
    if (IS_DEVELOPMENT) {
      const local = getLocalValues();
      if (local && local.has(name)) {
        console.warn(
          `[secrets] AWS Secrets Manager unavailable in development – ` +
          `using local fallback for "${name}". Error: ${smError.message}`
        );
        return local.get(name);
      }
    }

    // In production, or when the local fallback also has no value, re-throw.
    throw new Error(
      `[secrets] Failed to retrieve secret "${name}" from AWS Secrets Manager` +
      (IS_DEVELOPMENT ? ' and no local fallback was found.' : '.') +
      ` Cause: ${smError.message}`
    );
  }
}

/**
 * Returns the set of secret names that were declared in .env.test.
 * Useful for pre-flight checks or secret rotation tooling.
 *
 * @returns {ReadonlySet<string>}
 */
function getSecretNames() {
  return Object.freeze(new Set(SECRET_NAMES));
}

module.exports = { getSecret, getSecretNames };

'use strict';

/**
 * app.js
 *
 * Application entry-point. Secrets are resolved through secrets.js which
 * fetches values from AWS Secrets Manager (with a local .env.test fallback
 * when NODE_ENV=development). No secret value is ever embedded in source code.
 */

const express      = require('express');
const { getSecret, getSecretNames } = require('./secrets');

const app = express();

// ── Startup: verify all declared secrets are reachable ───────────────────────

/**
 * Resolves every secret declared in .env.test before the HTTP server opens
 * its port. If any secret cannot be fetched the process exits so that a
 * misconfigured deployment is caught immediately rather than failing at the
 * first request that needs a credential.
 *
 * The resolved values are returned as a plain object and should be passed
 * explicitly to the code that needs them instead of being stored in a
 * module-level variable.
 */
async function loadSecrets() {
  const names = getSecretNames();
  const resolved = {};

  for (const name of names) {
    resolved[name] = await getSecret(name);
  }

  return resolved;
}

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// ── Bootstrap ─────────────────────────────────────────────────────────────────

async function start() {
  let secrets;

  try {
    secrets = await loadSecrets();
  } catch (err) {
    console.error('[app] Secret resolution failed – aborting startup.', err.message);
    process.exit(1);
  }

  // Secrets are now available in `secrets` and can be passed explicitly to
  // database clients, API clients, etc.  Example:
  //
  //   await connectDatabase(secrets.DATABASE_URL);
  //   configureStripe(secrets.STRIPE_SECRET_KEY);
  //
  // Never log, serialise, or expose the `secrets` object through any API.

  console.log(`[app] Successfully loaded ${Object.keys(secrets).length} secret(s):`,
    Object.keys(secrets).join(', '));

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

start();

module.exports = app;

