#!/bin/bash
echo "=== Check secret values do NOT appear in JS files ==="

while IFS='=' read -r key value; do
  key=$(echo "$key" | tr -d '[:space:]')
  value=$(echo "$value" | tr -d '[:space:]')
  # Skip blank keys and comment lines
  case "$key" in ''|\#*) continue ;; esac
  [ -z "$value" ] && continue

  if grep -rn --include="*.js" -F "$value" . 2>/dev/null | grep -q .; then
    echo "FAIL: Value for '$key' found in a .js file!"
    grep -rn --include="*.js" -F "$value" .
  else
    echo "OK  : '$key' value is absent from all .js files"
  fi
done < .env.test

echo ""
echo "=== Confirm key names are NOT hardcoded in JS (only read dynamically) ==="
for key in DATABASE_URL AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY ANTHROPIC_API_KEY STRIPE_SECRET_KEY LOGFIRE_TOKEN; do
  hits=$(grep -rn --include="*.js" "$key" . 2>/dev/null)
  if [ -n "$hits" ]; then
    echo "NOTE: '$key' referenced in source (expected only in comments) →"
    echo "$hits"
  else
    echo "OK  : '$key' not hardcoded anywhere"
  fi
done

echo ""
echo "=== Confirm module exports via node ==="
node -e "
  const Module = require('module');
  const origResolve = Module._resolveFilename.bind(Module);
