  require.cache['@aws-sdk/client-secrets-manager'] = {
    id: '@aws-sdk/client-secrets-manager', filename: '@aws-sdk/client-secrets-manager',
    loaded: true,
    exports: {
      SecretsManagerClient: class { send() {} },
      GetSecretValueCommand: class {}
    }
  };
  const s = require('./secrets');
  console.log(typeof s.getSecret === 'function' && typeof s.getSecretNames === 'function'
