{
  "name": "secrets-manager-app",
  "version": "1.0.0",
  "description": "Express app using AWS Secrets Manager with .env.test fallback",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "NODE_ENV=development node app.js"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  }
}

/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * 1. On startup, parse .env.test to discover the *names* of every required
 *    secret (the values in that file are never used in production).
 * 2. In production (NODE_ENV=production) every call to getSecret() fetches the
 *    value from AWS Secrets Manager.
 * 3. In all other environments (development, test, CI) .env.test is loaded via
 *    dotenv and getSecret() reads from process.env — no AWS call is made.
 *
 * AWS secret layout
 * -----------------
 * Each secret is stored in Secrets Manager as a plain-string secret whose
 * Name matches the environment-variable key exactly, optionally prefixed by
 * the APP_SECRET_PREFIX environment variable (default: "").
 *
 *   e.g. APP_SECRET_PREFIX=myapp/prod  →  secret name = "myapp/prod/DATABASE_URL"
 *        APP_SECRET_PREFIX=""           →  secret name = "DATABASE_URL"
 *
 * AWS credentials / region
 * ------------------------
 * The SDK picks these up automatically from the standard chain:
 *   IAM role → ECS task role → ~/.aws/credentials → environment variables.
 * Set AWS_REGION (or AWS_DEFAULT_REGION) in the execution environment.
 * Do NOT put real AWS credentials in .env.test.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test to extract the list of required secret key names.
//     We read the file ourselves rather than calling dotenv.config() here so
//     that we control exactly when (and whether) values are written to
//     process.env — keeping that decision in one place below.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parse a dotenv-formatted file and return a Map of { key → value }.
 * Lines that are blank or start with # are skipped.
 * Inline # comments and surrounding quotes are stripped per dotenv rules.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Map<string, string>}
 */
function parseDotenvFile(filePath) {
  const entries = new Map();

  if (!fs.existsSync(filePath)) {
    console.warn(`[secrets] Warning: ${filePath} not found — no fallback values loaded.`);
    return entries;
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blanks and full-line comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key = line.slice(0, eqIdx).trim();

    // Strip optional inline comment (naïve but sufficient for well-formed files)
    let val = line.slice(eqIdx + 1).trim();

    // Strip surrounding single or double quotes
    if ((val.startsWith('"') && val.endsWith('"')) ||
        (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1);
    }

    if (key) {
      entries.set(key, val);
    }
  }

  return entries;
}

// The parsed file gives us the authoritative list of secret names.
const localSecrets = parseDotenvFile(ENV_FILE);

/** Sorted array of every secret key name found in .env.test */
const REQUIRED_SECRET_NAMES = [...localSecrets.keys()].sort();

// ---------------------------------------------------------------------------
// 2.  Environment detection
// ---------------------------------------------------------------------------

const IS_PRODUCTION = process.env.NODE_ENV === 'production';

// ---------------------------------------------------------------------------
// 3.  Development / test path — populate process.env from .env.test values
//     only when NOT in production.  This mirrors what `dotenv.config()` does
//     but keeps the logic transparent.
// ---------------------------------------------------------------------------

if (!IS_PRODUCTION) {
  // Lazily require dotenv only in non-production environments.
  // dotenv.config() will NOT overwrite variables already set in the shell,
  // which lets CI pipelines inject their own values without touching the file.
  const dotenv = require('dotenv');
  const result = dotenv.config({ path: ENV_FILE });

  if (result.error) {
    console.warn(`[secrets] dotenv could not load ${ENV_FILE}:`, result.error.message);
  } else {
    console.info(`[secrets] Loaded ${Object.keys(result.parsed || {}).length} secret(s) from ${ENV_FILE} (development fallback).`);
  }
}

// ---------------------------------------------------------------------------
// 4.  AWS Secrets Manager client — created lazily, only in production.
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * Return (creating if necessary) a SecretsManagerClient.
 * The client is a singleton so that the HTTP connection pool is reused.
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSecretsManagerClient() {
  if (!_smClient) {
    // Require is deferred so that non-production environments never need the
    // AWS SDK installed (useful for lightweight CI images).
    const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

    _smClient = new SecretsManagerClient({
      // Region resolution order:
      //   1. AWS_REGION env var  (set this in your deployment config)
      //   2. AWS_DEFAULT_REGION env var
      //   3. SDK instance metadata fallback (EC2 / ECS)
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION,
    });
  }
  return _smClient;
}

// ---------------------------------------------------------------------------
// 5.  In-process cache for production fetches.
//     Each entry: { value: string, fetchedAt: number (ms epoch) }
//     TTL is configurable via SECRET_CACHE_TTL_MS (default: 5 minutes).
// ---------------------------------------------------------------------------

const SECRET_CACHE_TTL_MS = parseInt(process.env.SECRET_CACHE_TTL_MS || '300000', 10);
const _secretCache = new Map(); // key → { value, fetchedAt }

/**
 * Fetch a secret value from AWS Secrets Manager, honouring the in-process
 * cache to avoid hammering the API on every request.
 *
 * @param {string} secretName  The full Secrets Manager secret name/ARN.
 * @returns {Promise<string>}
 */
async function fetchFromSecretsManager(secretName) {
  const now = Date.now();
  const cached = _secretCache.get(secretName);

  if (cached && (now - cached.fetchedAt) < SECRET_CACHE_TTL_MS) {
    return cached.value;
  }

  const {
    GetSecretValueCommand,
  } = require('@aws-sdk/client-secrets-manager');

  const client = getSecretsManagerClient();

  let response;
  try {
    response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
  } catch (err) {
    // Surface a clear, actionable error — never swallow it silently.
    throw new Error(
      `[secrets] Failed to retrieve secret "${secretName}" from AWS Secrets Manager: ${err.message}`
    );
  }

  // Secrets Manager returns either SecretString (text/JSON) or SecretBinary.
  let value;
  if (typeof response.SecretString !== 'undefined') {
    value = response.SecretString;
  } else if (response.SecretBinary) {
    value = Buffer.from(response.SecretBinary).toString('utf8');
  } else {
    throw new Error(`[secrets] Secret "${secretName}" returned no value from Secrets Manager.`);
  }

  _secretCache.set(secretName, { value, fetchedAt: now });
  return value;
}

// ---------------------------------------------------------------------------
// 6.  Public API
// ---------------------------------------------------------------------------

/**
 * Build the full Secrets Manager secret name for a given key.
 * Respects the optional APP_SECRET_PREFIX environment variable.
 *
 * @param {string} key  The bare key name, e.g. "DATABASE_URL".
 * @returns {string}    e.g. "myapp/prod/DATABASE_URL" or just "DATABASE_URL".
 */
function buildSecretName(key) {
  const prefix = (process.env.APP_SECRET_PREFIX || '').replace(/\/$/, '');
  return prefix ? `${prefix}/${key}` : key;
}

/**
 * Retrieve a secret value by its key name.
 *
 * In **production** the value is fetched from AWS Secrets Manager (with
 * in-process caching).  In **development / test** the value is read from
 * process.env, which was populated from .env.test by dotenv above.
 *
 * @param {string} name  The secret key name as it appears in .env.test,
 *                       e.g. "DATABASE_URL".
 * @returns {Promise<string>}  Resolves to the secret value.
 * @throws  If the secret is not found or the Secrets Manager call fails.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    // Warn loudly — callers should only request secrets declared in .env.test
    // so that local development always has a working fallback.
    console.warn(`[secrets] Warning: "${name}" is not listed in ${ENV_FILE}. Proceeding anyway.`);
  }

  if (IS_PRODUCTION) {
    const secretName = buildSecretName(name);
    return fetchFromSecretsManager(secretName);
  }

  // Non-production: read from process.env (populated by dotenv above).
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(
      `[secrets] Secret "${name}" is not set in process.env. ` +
      `Ensure ${ENV_FILE} contains a "${name}=" line.`
    );
  }
  return value;
}

/**
 * Pre-warm the secret cache by fetching all required secrets in parallel.
 * Call this once during application startup (production) to front-load
 * latency rather than paying it on the first real request.
 *
 * In development this is a no-op (values are already in process.env).
 *
 * @returns {Promise<void>}
 */
async function preloadSecrets() {
  if (!IS_PRODUCTION) {
    console.info('[secrets] preloadSecrets() skipped in non-production environment.');
    return;
  }

  console.info(`[secrets] Pre-loading ${REQUIRED_SECRET_NAMES.length} secret(s) from AWS Secrets Manager…`);

  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map((name) => getSecret(name))
  );

  const failed = results
    .map((r, i) => (r.status === 'rejected' ? REQUIRED_SECRET_NAMES[i] : null))
    .filter(Boolean);

  if (failed.length > 0) {
    throw new Error(
      `[secrets] Failed to pre-load the following secret(s): ${failed.join(', ')}. ` +
      'Application startup aborted.'
    );
  }

  console.info('[secrets] All secrets pre-loaded successfully.');
}

// ---------------------------------------------------------------------------
// 7.  Exports
// ---------------------------------------------------------------------------

module.exports = {
  /**
   * Sorted list of every secret key name declared in .env.test.
   * Use this to validate configuration or iterate over all secrets.
   * @type {string[]}
   */
  REQUIRED_SECRET_NAMES,

  /**
   * Fetch a secret by name.  Secrets Manager in production; process.env in dev.
   * @type {(name: string) => Promise<string>}
   */
  getSecret,

  /**
   * Pre-warm all secrets at startup (production only).
   * @type {() => Promise<void>}
   */
  preloadSecrets,
};

'use strict';

/**
 * app.js
 *
 * Express application entry point.
 *
 * Secrets are never hard-coded or imported directly from .env.test.
 * All secret access goes through secrets.getSecret(), which routes to
 * AWS Secrets Manager in production and to the local .env.test fallback
 * in development / test environments.
 */

const express = require('express');
const { getSecret, preloadSecrets, REQUIRED_SECRET_NAMES } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * GET /config-check
 *
 * Verifies that every secret listed in .env.test can be resolved at runtime.
 * Returns the key names and resolution status — never the secret values.
 *
 * Useful as a startup readiness probe in CI or during deployment.
 */
app.get('/config-check', async (req, res) => {
  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map((name) => getSecret(name))
  );

  const report = REQUIRED_SECRET_NAMES.map((name, i) => ({
    name,
    resolved: results[i].status === 'fulfilled',
    // Never include the secret value — only report resolution status.
    error: results[i].status === 'rejected' ? results[i].reason.message : undefined,
  }));

  const allResolved = report.every((r) => r.resolved);

  res.status(allResolved ? 200 : 500).json({
    ok: allResolved,
    secrets: report,
  });
});

/**
 * Example route demonstrating how a handler retrieves a specific secret
 * on demand, without ever touching process.env directly or hard-coding values.
 *
 * In a real application you would use the resolved value (e.g. open a DB
 * connection) rather than acknowledging its presence.
 */
app.get('/db-ping', async (req, res) => {
  let dbUrl;
  try {
    dbUrl = await getSecret('DATABASE_URL');
  } catch (err) {
    console.error('[app] Could not retrieve DATABASE_URL:', err.message);
    return res.status(500).json({ error: 'Secret unavailable. Check server logs.' });
  }

  // Use the secret — here we just confirm we have a non-empty value.
  // DO NOT log or return the secret value itself.
  res.json({
    connected: typeof dbUrl === 'string' && dbUrl.length > 0,
    message: 'DATABASE_URL resolved successfully.',
