'use strict';

/**
 * secrets.js
 *
 * Centralised secret resolution with two-tier strategy:
 *
 *   1. PRIMARY  – AWS Secrets Manager (used in staging / production).
 *   2. FALLBACK – .env.test loaded via dotenv (used in local development
 *                 when NODE_ENV === 'development' or the AWS call fails
 *                 because no real credentials are present).
 *
 * Required secret names are discovered automatically by parsing .env.test,
 * so the source of truth for *which* secrets the application needs is always
 * that single file — no name is ever hardcoded here.
 *
 * Usage
 * -----
 *   const { getSecret } = require('./secrets');
 *
 *   // Async – preferred
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Synchronous convenience (only safe after initSecrets() has resolved)
 *   const dbUrl = getSecretSync('DATABASE_URL');
 *
 * Initialisation
 * --------------
 *   Call initSecrets() once at application start-up and await it before
 *   serving traffic.  It pre-warms the in-process cache so that all
 *   subsequent getSecret() calls are instant.
 */

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret names
//    We deliberately do NOT import all the values — we only read the *keys*.
//    The file is the registry of required secret names; actual values come
//    from Secrets Manager (or the file itself as a dev fallback).
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Returns the list of secret names declared in .env.test.
 * Lines starting with '#' and blank lines are skipped.
 *
 * @returns {string[]}
 */
function parseRequiredSecretNames() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] ${ENV_FILE} not found – no required secret names loaded.`);
    return [];
  }

  const lines = fs.readFileSync(ENV_FILE, 'utf8').split('\n');

  return lines
    .map(line => line.trim())
    .filter(line => line.length > 0 && !line.startsWith('#'))
    .map(line => {
      // Accept both KEY=value and export KEY=value forms.
      const withoutExport = line.replace(/^export\s+/, '');
      const eqIdx = withoutExport.indexOf('=');
      return eqIdx !== -1 ? withoutExport.slice(0, eqIdx).trim() : null;
    })
    .filter(Boolean);
}

/** Immutable list of secret names this application requires. */
const REQUIRED_SECRET_NAMES = Object.freeze(parseRequiredSecretNames());

// ---------------------------------------------------------------------------
// 2. Lazy-load AWS SDK so the module can still be required in environments
//    where the SDK is not installed (e.g. a stripped-down CI image that only
//    runs linting).  The actual SDK import is deferred to first use.
// ---------------------------------------------------------------------------

let _smClient = null; // SecretsManagerClient singleton

function getSmClient() {
  if (_smClient) return _smClient;

  // Throws at runtime if the package is not installed — intentional: the
  // error message from Node is clear enough to diagnose the missing dep.
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  _smClient = new SecretsManagerClient({
    // Region is read from the standard AWS_REGION / AWS_DEFAULT_REGION env
    // vars or the shared config file — never hardcoded.
    region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
  });

