// 3. .env.test fallback  (development / offline use)
//    Values are loaded lazily and cached so the file is read at most once.
// ---------------------------------------------------------------------------

let _envFallback = null; // { KEY: 'value', ... }

/**
 * Loads .env.test into a plain object without mutating process.env.
 * Uses dotenv's parse() helper so we get the same quoting / escaping rules.
 */
function loadEnvFallback() {
  if (_envFallback) return _envFallback;

  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`[secrets] Fallback file ${ENV_FILE} not found.`);
    _envFallback = {};
    return _envFallback;
  }

  try {
    const dotenv = require('dotenv');
    const raw    = fs.readFileSync(ENV_FILE);
    _envFallback = dotenv.parse(raw); // returns { KEY: 'value', ... }
    console.info('[secrets] Fallback .env.test parsed (development mode).');
  } catch (err) {
    console.error('[secrets] Failed to parse .env.test fallback:', err.message);
    _envFallback = {};
