// ---------------------------------------------------------------------------
// 4. In-process cache
//    Avoids repeated network round-trips to Secrets Manager within a single
//    process lifetime.  Keys are secret names; values are the resolved
//    plaintext strings.
// ---------------------------------------------------------------------------

const _cache = new Map(); // name -> resolved value

// ---------------------------------------------------------------------------
// 5. Core fetch logic
// ---------------------------------------------------------------------------

const IS_DEVELOPMENT = process.env.NODE_ENV === 'development';

/**
 * Fetches a single secret from AWS Secrets Manager.
 *
 * @param {string} name  The Secrets Manager secret name or ARN.
 * @returns {Promise<string>}
 * @throws  If the secret does not exist or the caller lacks permission.
 */
async function fetchFromSecretsManager(name) {
  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

  const response = await getSmClient().send(
    new GetSecretValueCommand({ SecretId: name })
  );

  // Secrets Manager returns either SecretString or SecretBinary.
  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  if (response.SecretBinary !== undefined) {
    // Binary secrets are returned as a Buffer; decode to UTF-8 string.
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

