    const value = fallback[name];
    _cache.set(name, value);

    if (!IS_DEVELOPMENT) {
      // Warn loudly when the fallback is used unexpectedly in a non-dev env.
      console.warn(
        `[secrets] WARNING: Using .env.test fallback for "${name}" in a non-development environment.`
