'use strict';

/**
 * secrets.js
 *
 * Provides a unified getSecret(name) function that resolves secret values in
 * priority order:
 *
 *   1. AWS Secrets Manager  (always attempted first in production)
 *   2. .env.test fallback   (used when NODE_ENV=development, or when Secrets
 *                            Manager is unreachable and NODE_ENV !== production)
 *
 * Secret *names* are derived exclusively from the keys present in .env.test so
 * that no secret name — let alone any value — is ever hardcoded here.
 *
 * Usage:
 *   const { getSecret, loadAllSecrets } = require('./secrets');
 *
 *   // Fetch a single secret (async):
 *   const dbUrl = await getSecret('DATABASE_URL');
 *
 *   // Pre-warm all secrets into the in-process cache at startup:
 *   await loadAllSecrets();
 */

const path = require('path');
const fs = require('fs');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1.  Discover required secret names from .env.test (keys only, never values)
// ---------------------------------------------------------------------------

/**
 * Parse a .env file and return an array of the *key names* it contains.
 * Lines that are blank or begin with '#' are skipped.
 * No values are retained — we only care about names.
 *
 * @param {string} envFilePath  Absolute or relative path to the .env file.
 * @returns {string[]}          Ordered list of key names.
 */
function parseEnvKeys(envFilePath) {
  const absolutePath = path.resolve(envFilePath);

  if (!fs.existsSync(absolutePath)) {
    console.warn(`[secrets] .env file not found at ${absolutePath} — no keys loaded`);
    return [];
  }

  const lines = fs.readFileSync(absolutePath, 'utf8').split('\n');
  const keys = [];

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    // KEY=value  →  take only what is left of the first '='
    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key = line.slice(0, eqIdx).trim();
    if (key) keys.push(key);
  }

  return keys;
}

// The canonical list of secret names this application needs.
// Derived purely from .env.test key names — zero values captured here.
const ENV_FILE = path.resolve(__dirname, '.env.test');
const REQUIRED_SECRET_NAMES = parseEnvKeys(ENV_FILE);

// ---------------------------------------------------------------------------
// 2.  Load .env.test values into a local map (development / fallback only)
// ---------------------------------------------------------------------------

/**
 * Load the actual values from .env.test into an in-memory map.
 * This is deliberately deferred — called only when a fallback is needed —
 * so production paths never read the file at all.
 *
 * @returns {Map<string, string>}
 */
function loadEnvFileValues() {
  const map = new Map();

  if (!fs.existsSync(ENV_FILE)) return map;

  // Use dotenv's parse helper so we get proper quoting / escape handling.
  // We import lazily so that dotenv is only required when actually needed.
  const dotenv = require('dotenv'); // eslint-disable-line global-require
  const parsed = dotenv.parse(fs.readFileSync(ENV_FILE));

  for (const [key, value] of Object.entries(parsed)) {
    map.set(key, value);
  }

  return map;
}

// ---------------------------------------------------------------------------
// 3.  AWS Secrets Manager client (lazy-initialised once)
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * Return a cached SecretsManagerClient.
 * Region is read from the AWS_REGION environment variable (or us-east-1).
 * No credentials are hard-coded; the SDK's default credential provider chain
 * is used (IAM role → env vars → ~/.aws/credentials → …).
 */
function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

// ---------------------------------------------------------------------------
// 4.  In-process cache so each secret is fetched from Secrets Manager once
// ---------------------------------------------------------------------------

/** @type {Map<string, string>} */
const _cache = new Map();

// ---------------------------------------------------------------------------
// 5.  Core resolution logic
// ---------------------------------------------------------------------------

const IS_PRODUCTION = process.env.NODE_ENV === 'production';
const IS_DEVELOPMENT = process.env.NODE_ENV === 'development';

/**
 * Attempt to fetch a secret value from AWS Secrets Manager.
 *
 * @param {string} name  The secret name / ARN.
 * @returns {Promise<string|null>}  The secret string, or null on failure.
 */
async function fetchFromSecretsManager(name) {
  try {
    const client = getSmClient();
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await client.send(command);

    // Secrets Manager returns either SecretString or SecretBinary.
    if (response.SecretString !== undefined) {
      return response.SecretString;
    }

    if (response.SecretBinary) {
      // Binary secret — decode from Base64 buffer to string.
      return Buffer.from(response.SecretBinary).toString('utf8');
    }

    return null;
  } catch (err) {
    // Surface meaningful context without leaking the secret value.
    console.error(`[secrets] Secrets Manager fetch failed for "${name}": ${err.message}`);
    return null;
  }
}

/**
 * Fetch a secret value from .env.test (development / fallback only).
 *
 * @param {string} name
 * @returns {string|null}
 */
