  if (_cache.has(name)) {
    return _cache.get(name);
  }

  // 2. Attempt Secrets Manager in all environments.
  //    In development this is skipped by default unless ENABLE_SM_IN_DEV=true,
  //    which keeps local iteration fast without an AWS connection.
  let value = null;

  const skipSm = IS_DEVELOPMENT && process.env.ENABLE_SM_IN_DEV !== 'true';

  if (!skipSm) {
    value = await fetchFromSecretsManager(name);
  }

  // 3. Fallback to .env.test for local development or non-production on error.
  if (value === null) {
    if (IS_PRODUCTION) {
      // Hard failure: never silently run production without a real secret.
      throw new Error(
        `[secrets] Secret "${name}" could not be retrieved from AWS Secrets Manager ` +
          `and .env.test fallback is disabled in production.`
      );
    }

