  console.log(`[secrets] Loading ${REQUIRED_SECRET_NAMES.length} secret(s): ${REQUIRED_SECRET_NAMES.join(', ')}`);

  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map((name) => getSecret(name))
  );

