    if (results[i].status === 'rejected') {
      console.error(`[secrets] Failed to load secret "${REQUIRED_SECRET_NAMES[i]}": ${results[i].reason?.message}`);
      failures++;
    }
  }

  if (failures > 0 && IS_PRODUCTION) {
    throw new Error(`[secrets] ${failures} secret(s) failed to load — refusing to start in production.`);
  }

  console.log(`[secrets] Secret loading complete (${REQUIRED_SECRET_NAMES.length - failures} ok, ${failures} failed).`);
  return _cache;
