  /** Ordered list of secret key names read from .env.test (no values). */
  REQUIRED_SECRET_NAMES,

  /**
   * Resolve a secret by name.
   * Tries Secrets Manager first; falls back to .env.test outside production.
   * Results are cached in-process.
   *
   * @type {(name: string) => Promise<string>}
   */
  getSecret,

  /**
   * Pre-warm the secret cache for all keys discovered in .env.test.
   * Recommended at application startup.
   *
   * @type {() => Promise<Map<string, string>>}
   */
  loadAllSecrets,
};

'use strict';

/**
 * app.js
 *
 * Express application entry point.
 *
 * Secrets are resolved through secrets.js — never read from environment
 * variables directly, and never hardcoded.  The module handles AWS Secrets
 * Manager with automatic .env.test fallback for local development.
 */

const express = require('express');
const { loadAllSecrets, getSecret } = require('./secrets');

const app = express();

// ---------------------------------------------------------------------------
// Boot sequence — load all secrets before accepting requests
// ---------------------------------------------------------------------------

async function start() {
  // Pre-warm the secret cache.  This validates that every secret listed in
  // .env.test is accessible (from Secrets Manager or the local fallback) and
  // surfaces misconfiguration at startup rather than mid-request.
  await loadAllSecrets();

  // ---------------------------------------------------------------------------
  // Routes
  // ---------------------------------------------------------------------------

  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  /**
   * Example: demonstrate that secrets are available to route handlers without
   * being included in responses.  In a real app, getSecret() would be called
   * inside service/db modules rather than directly in routes.
   *
   * GET /secret-demo  →  confirms a named secret was resolved (never its value)
   */
  app.get('/secret-demo', async (req, res) => {
    const { name } = req.query;

    if (!name) {
      return res.status(400).json({ error: 'Query param "name" is required.' });
    }

    try {
      const value = await getSecret(name);          // value used by the handler …
      void value;                                   // … but never sent in the response
      return res.json({
        secret: name,
        resolved: true,
        length: value.length,                       // length is safe metadata, not the value
      });
    } catch (err) {
      return res.status(404).json({ error: err.message });
    }
  });

  // ---------------------------------------------------------------------------
  // Start listening
  // ---------------------------------------------------------------------------

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

start().catch((err) => {
  console.error('[app] Fatal startup error:', err.message);
  process.exit(1);
});

