/**
 * Minimal .env parser that handles the common subset of the dotenv spec:
 *   - KEY=value
 *   - KEY="quoted value"
 *   - KEY='single quoted'
 *   - Inline # comments (outside quotes)
 *   - Blank lines and full-line # comments are skipped
 *
 * Used as the primary parser so that the module has zero hard runtime
 * dependencies.  When dotenv is installed its richer parser is preferred
 * (better escape-sequence support), but this fallback is always available.
 *
 * @param {string} src  Raw file contents.
 * @returns {Object.<string, string>}
 */
function parseEnvValues(src) {
  const result = {};

  for (const rawLine of src.split('\n')) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key = line.slice(0, eqIdx).trim();
    if (!key) continue;

    let val = line.slice(eqIdx + 1); // everything after the first '='

    // Strip inline comment (only when the value is not quoted)
    const firstChar = val.charAt(0);
    if (firstChar !== '"' && firstChar !== "'") {
      const commentIdx = val.indexOf(' #');
      if (commentIdx !== -1) val = val.slice(0, commentIdx);
      val = val.trim();
    } else {
      // Strip matching outer quotes and unescape \" / \'
      const quote = firstChar;
      const closeIdx = val.lastIndexOf(quote);
      if (closeIdx > 0) {
        val = val.slice(1, closeIdx).replace(new RegExp(`\\\\${quote}`, 'g'), quote);
      } else {
        val = val.slice(1); // no closing quote found — take as-is
      }
    }

    result[key] = val;
  }

  return result;
}

/**
 * Load the actual values from .env.test into an in-memory map.
 * This is deliberately deferred — called only when a fallback is needed —
 * so production paths never read the file at all.
 *
 * Prefers dotenv's parser when the package is available (richer escape
 * handling); otherwise falls back to the built-in parseEnvValues() above.
 *
 * @returns {Map<string, string>}
 */
function loadEnvFileValues() {
  const map = new Map();

  if (!fs.existsSync(ENV_FILE)) return map;

  const raw = fs.readFileSync(ENV_FILE);
  let parsed;

  try {
    // eslint-disable-next-line global-require
    const dotenv = require('dotenv');
    parsed = dotenv.parse(raw);
  } catch {
    // dotenv not installed — use the built-in parser
    parsed = parseEnvValues(raw.toString('utf8'));
  }

  for (const [key, value] of Object.entries(parsed)) {
    map.set(key, value);
  }

  return map;
}

