/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * 1. At module load time, parse .env.test with dotenv to discover which secret
 *    names the application needs.  The *values* from that file are only used as
 *    a local development fallback — they are never forwarded to AWS.
 * 2. getSecret(name) tries AWS Secrets Manager first (when the AWS environment
 *    is reachable and NODE_ENV !== 'development').  On any AWS error it falls
 *    back to the value that dotenv loaded from .env.test and emits a warning so
 *    the fallback is always visible in logs.
 * 3. If neither source can supply a value the call throws, preventing the app
 *    from starting with a missing secret.
 *
 * Environment variables that influence behaviour
 * -----------------------------------------------
 *   NODE_ENV            – set to 'development' to skip AWS and use .env.test
 *                         directly (useful on a laptop without AWS credentials).
 *   AWS_REGION          – AWS region for Secrets Manager (default: us-east-1).
 *   AWS_SM_SECRET_ID    – optional prefix/path prepended to every secret name
 *                         when building the Secrets Manager SecretId, e.g.
 *                         "myapp/prod".  If omitted the bare name is used.
 *
 * No secret values are hard-coded in this file.
 */

'use strict';

const path = require('path');
const fs   = require('fs');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1. Load .env.test to discover required secret names + local fallback values.
//    We parse the file directly so we can inspect the key list without
//    polluting process.env any more than dotenv already would.
// ---------------------------------------------------------------------------
