if (!fs.existsSync(ENV_FILE)) {
  throw new Error(`secrets.js: cannot find required env file at ${ENV_FILE}`);
}

// dotenv.config() merges into process.env; dotenv.parse() gives us a plain
// object.  We use parse() to keep the source-of-truth isolated.
const envFileContents = fs.readFileSync(ENV_FILE);
const localSecrets    = dotenv.parse(envFileContents); // { NAME: 'value', … }

/** The canonical list of secret names the application requires, derived
 *  entirely from the keys present in .env.test. */
const REQUIRED_SECRET_NAMES = Object.freeze(Object.keys(localSecrets));

// ---------------------------------------------------------------------------
// 2. Build the Secrets Manager client (created lazily so unit tests can swap
//    it out before the first call).
// ---------------------------------------------------------------------------
let _smClient = null;

function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

/** Inject a custom client — useful in tests (e.g. pass a mock). */
