  _smClient = client;
}

// ---------------------------------------------------------------------------
// 3. Core helper — fetch a single secret string from Secrets Manager.
//    The SecretId sent to AWS is optionally prefixed by AWS_SM_SECRET_ID so
//    that the same code can target different environments without code changes.
// ---------------------------------------------------------------------------
async function fetchFromSecretsManager(name) {
  const prefix   = process.env.AWS_SM_SECRET_ID ? `${process.env.AWS_SM_SECRET_ID}/` : '';
  const secretId = `${prefix}${name}`;

  const command  = new GetSecretValueCommand({ SecretId: secretId });
  const response = await getSmClient().send(command);

  // AWS returns the value in either SecretString (text/JSON) or
  // SecretBinary (base64-encoded).  We handle both.
  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary, 'base64').toString('utf8');
  }

  throw new Error(`secrets.js: Secrets Manager returned an empty payload for '${secretId}'`);
