    const anthropicKey  = await getSecret('ANTHROPIC_API_KEY');
    const logfireToken  = await getSecret('LOGFIRE_TOKEN');

    // --- Wire up services with the resolved secrets ---
    // (Placeholder comments show where real SDK initialisations would go.
    //  The actual secret strings are intentionally not logged or exported.)

    // e.g. await db.connect(dbUrl);
