# We mock the two unavailable packages so the logic can be exercised without
# a real npm install, then exercise every exported function.
node - << 'EOF'
'use strict';

// ── Minimal stubs for packages not yet installed ─────────────────────────────
const Module = require('module');
const _orig  = Module._resolveFilename.bind(Module);

// Stub @aws-sdk/client-secrets-manager
const fakeAwsError = new Error('simulated AWS unreachable');
const fakeSmClient = {
  send: async () => { throw fakeAwsError; }
};
class GetSecretValueCommand { constructor(input) { this.input = input; } }
class SecretsManagerClient  { constructor() {} send(...a) { return fakeSmClient.send(...a); } }

// Stub dotenv
const dotenv = {
  parse: (buf) => {
    // Minimal key=value parser (handles comments and blank lines)
    const out = {};
    buf.toString().split('\n').forEach(line => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;
      const eq = trimmed.indexOf('=');
      if (eq === -1) return;
      out[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
    });
    return out;
  }
};

// Intercept require() calls for the two stubs
const origLoad = Module._load.bind(Module);
Module._load = function(request, parent, isMain) {
  if (request === '@aws-sdk/client-secrets-manager') {
    return { SecretsManagerClient, GetSecretValueCommand };
  }
  if (request === 'dotenv') {
    return dotenv;
  }
  return origLoad(request, parent, isMain);
};

// ── Load secrets.js ───────────────────────────────────────────────────────────
const secrets = require('./secrets');

(async () => {
  // 1. getRequiredSecretNames() must return exactly the keys from .env.test
  const names = secrets.getRequiredSecretNames();
  const expected = [
    'DATABASE_URL','AWS_ACCESS_KEY_ID','AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY','STRIPE_SECRET_KEY','LOGFIRE_TOKEN'
  ];
  console.assert(
    JSON.stringify(names.sort()) === JSON.stringify(expected.sort()),
    'FAIL: secret names do not match .env.test keys'
  );
  console.log('PASS: getRequiredSecretNames() returns all .env.test keys');

  // 2. In NODE_ENV=development getSecret() must use the local fallback
  process.env.NODE_ENV = 'development';
  secrets._clearCache();
  const dbUrl = await secrets.getSecret('DATABASE_URL');
  console.assert(
    dbUrl === 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
    'FAIL: dev fallback value mismatch'
  );
  console.log('PASS: getSecret() returns .env.test value in development mode');

  // 3. Unknown secret name must throw
  try {
    await secrets.getSecret('NONEXISTENT_KEY');
    console.log('FAIL: should have thrown for unknown secret');
  } catch (e) {
    console.assert(e.message.includes('not a recognised secret'), 'FAIL: wrong error message');
    console.log('PASS: getSecret() throws for unregistered secret name');
  }

  // 4. Production mode: AWS fails → fallback to .env.test with a warning
  process.env.NODE_ENV = 'production';
  secrets._clearCache();
  const stripeKey = await secrets.getSecret('STRIPE_SECRET_KEY');
  console.assert(
    stripeKey === 'REDACTED_STRIPE_LIVE',
    'FAIL: production fallback value mismatch'
  );
  console.log('PASS: getSecret() falls back to .env.test when AWS is unreachable');

  // 5. Production mode with a working AWS client
  secrets._clearCache();
  const workingClient = {
    send: async (cmd) => ({ SecretString: 'live-secret-from-aws-' + cmd.input.SecretId })
  };
  secrets.setSmClient(workingClient);
  const anthropicKey = await secrets.getSecret('ANTHROPIC_API_KEY');
  console.assert(
    anthropicKey.startsWith('live-secret-from-aws-'),
    'FAIL: expected AWS-sourced value'
  );
  console.log('PASS: getSecret() returns AWS Secrets Manager value when client succeeds');

  // 6. loadAllSecrets() pre-warms cache for all names
  secrets._clearCache();
  await secrets.loadAllSecrets();
  const cachedNames = secrets.getRequiredSecretNames();
  console.log(`PASS: loadAllSecrets() completed for ${cachedNames.length} secrets`);

  console.log('\nAll smoke-tests passed.');
})().catch(err => { console.error('UNEXPECTED ERROR:', err); process.exit(1); });
EOF

