/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * 1. At module load time, parse .env.test with dotenv to discover which secret
 *    names the application needs.  The *values* from that file are only used as
 *    a local development fallback — they are never forwarded to AWS.
 * 2. getSecret(name) tries AWS Secrets Manager first (when the AWS environment
 *    is reachable and NODE_ENV !== 'development').  On any AWS error it falls
 *    back to the value that dotenv loaded from .env.test and emits a warning so
 *    the fallback is always visible in logs.
 * 3. If neither source can supply a value the call throws, preventing the app
 *    from starting with a missing secret.
 *
 * Environment variables that influence behaviour
 * -----------------------------------------------
 *   NODE_ENV            – set to 'development' to skip AWS and use .env.test
 *                         directly (useful on a laptop without AWS credentials).
 *   AWS_REGION          – AWS region for Secrets Manager (default: us-east-1).
 *   AWS_SM_SECRET_ID    – optional prefix/path prepended to every secret name
 *                         when building the Secrets Manager SecretId, e.g.
 *                         "myapp/prod".  If omitted the bare name is used.
 *
 * No secret values are hard-coded in this file.
 */

'use strict';

const path = require('path');
const fs   = require('fs');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1. Load .env.test to discover required secret names + local fallback values.
//    We parse the file directly so we can inspect the key list without
//    polluting process.env any more than dotenv already would.
// ---------------------------------------------------------------------------
const ENV_FILE = path.resolve(__dirname, '.env.test');

if (!fs.existsSync(ENV_FILE)) {
  throw new Error(`secrets.js: cannot find required env file at ${ENV_FILE}`);
}

// dotenv.config() merges into process.env; dotenv.parse() gives us a plain
// object.  We use parse() to keep the source-of-truth isolated.
const envFileContents = fs.readFileSync(ENV_FILE);
const localSecrets    = dotenv.parse(envFileContents); // { NAME: 'value', … }

/** The canonical list of secret names the application requires, derived
 *  entirely from the keys present in .env.test. */
const REQUIRED_SECRET_NAMES = Object.freeze(Object.keys(localSecrets));

// ---------------------------------------------------------------------------
// 2. Build the Secrets Manager client (created lazily so unit tests can swap
//    it out before the first call).
// ---------------------------------------------------------------------------
let _smClient = null;

function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

/** Inject a custom client — useful in tests (e.g. pass a mock). */
function setSmClient(client) {
  _smClient = client;
}

// ---------------------------------------------------------------------------
// 3. Core helper — fetch a single secret string from Secrets Manager.
//    The SecretId sent to AWS is optionally prefixed by AWS_SM_SECRET_ID so
//    that the same code can target different environments without code changes.
// ---------------------------------------------------------------------------
async function fetchFromSecretsManager(name) {
  const prefix   = process.env.AWS_SM_SECRET_ID ? `${process.env.AWS_SM_SECRET_ID}/` : '';
  const secretId = `${prefix}${name}`;

  const command  = new GetSecretValueCommand({ SecretId: secretId });
  const response = await getSmClient().send(command);

  // AWS returns the value in either SecretString (text/JSON) or
  // SecretBinary (base64-encoded).  We handle both.
  if (response.SecretString !== undefined) {
    return response.SecretString;
  }

  if (response.SecretBinary) {
    return Buffer.from(response.SecretBinary, 'base64').toString('utf8');
  }

  throw new Error(`secrets.js: Secrets Manager returned an empty payload for '${secretId}'`);
}

// ---------------------------------------------------------------------------
// 4. In-process cache so each secret is fetched at most once per process.
// ---------------------------------------------------------------------------
const cache = new Map(); // name → resolved string value

// ---------------------------------------------------------------------------
// 5. Public API
// ---------------------------------------------------------------------------

/**
 * Returns the list of secret names discovered from .env.test.
 * Useful for pre-warming the cache at startup (see loadAllSecrets).
 *
 * @returns {string[]}
 */
function getRequiredSecretNames() {
  return [...REQUIRED_SECRET_NAMES];
}

/**
 * Fetch a secret by name.
 *
 * Resolution order:
 *   a) In-process cache (populated by a previous call or loadAllSecrets).
 *   b) AWS Secrets Manager — unless NODE_ENV === 'development'.
 *   c) Local fallback: the value from .env.test (with a warning).
 *
 * Throws if the name was not present in .env.test (unknown secret) or if
 * neither AWS nor the local file could supply a value.
 *
 * @param   {string} name  – exact key as it appears in .env.test
 * @returns {Promise<string>}
 */
async function getSecret(name) {
  // Guard: only allow names that were declared in .env.test so callers cannot
  // accidentally probe arbitrary Secrets Manager paths.
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    throw new Error(
      `secrets.js: '${name}' is not a recognised secret. ` +
      `Add it to .env.test (with a canary/placeholder value) to register it.`
    );
  }

  // Return from cache if already resolved.
  if (cache.has(name)) {
    return cache.get(name);
  }

  const isDev = process.env.NODE_ENV === 'development';

  if (!isDev) {
    // --- Try AWS Secrets Manager ---
    try {
      const value = await fetchFromSecretsManager(name);
      cache.set(name, value);
      return value;
    } catch (awsErr) {
      // Surface the AWS error clearly, then fall through to local fallback.
      console.warn(
        `[secrets] WARNING: could not fetch '${name}' from AWS Secrets Manager ` +
        `(${awsErr.message}). Falling back to .env.test value. ` +
        `Do NOT use this fallback in production.`
      );
    }
  }

  // --- Local .env.test fallback ---
  const fallback = localSecrets[name];
  if (fallback === undefined || fallback === '') {
    throw new Error(
      `secrets.js: '${name}' has no value in .env.test and could not be ` +
      `fetched from AWS Secrets Manager.`
    );
  }

  if (isDev) {
    console.info(`[secrets] DEV mode — using .env.test value for '${name}'.`);
  }

  cache.set(name, fallback);
  return fallback;
}

/**
 * Pre-warm the cache by fetching every secret listed in .env.test.
 * Call this once during application startup (before handling requests) so
 * that individual request handlers never have to await a cold secret fetch.
 *
 * Rejects if any single secret cannot be resolved, causing the process to
 * refuse to start rather than serving requests with missing credentials.
 *
 * @returns {Promise<void>}
 */
async function loadAllSecrets() {
  console.info(`[secrets] Loading ${REQUIRED_SECRET_NAMES.length} secret(s): ${REQUIRED_SECRET_NAMES.join(', ')}`);
  await Promise.all(REQUIRED_SECRET_NAMES.map(name => getSecret(name)));
  console.info('[secrets] All secrets loaded successfully.');
}

/**
 * Clear the in-process cache.  Intended for use in tests only.
 */
function _clearCache() {
  cache.clear();
}

module.exports = {
  getSecret,
  loadAllSecrets,
  getRequiredSecretNames,
  setSmClient,   // test helper
  _clearCache,   // test helper
};

/**
 * app.js
 *
 * Application entry point.
 *
 * Secrets are loaded via secrets.js, which fetches them from AWS Secrets
 * Manager (production) or falls back to .env.test (development).
 * No secret values are hard-coded here.
 */

'use strict';

const express = require('express');
const { loadAllSecrets, getSecret } = require('./secrets');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * Example route that demonstrates runtime secret access.
 * A real handler would use the retrieved value directly (e.g. to open a DB
 * connection) rather than returning metadata about it.
 */
app.get('/secret-status', async (req, res) => {
  try {
    const { getRequiredSecretNames } = require('./secrets');
    const names    = getRequiredSecretNames();
    const statuses = await Promise.all(
      names.map(async name => {
        try {
          const value = await getSecret(name);
          // Never expose the value — only confirm it is present and show its
          // length so callers can verify the right secret was fetched.
          return { name, loaded: true, length: value.length };
        } catch (err) {
          return { name, loaded: false, error: err.message };
        }
      })
    );
    res.json({ secrets: statuses });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Startup — load all secrets before accepting traffic
// ---------------------------------------------------------------------------

async function start() {
  try {
    // Pre-warm the secret cache so request handlers never block on a cold
    // fetch and so that a missing/unreachable secret aborts startup cleanly.
    await loadAllSecrets();

    // Use secrets to configure services.
    // Access each value exactly once here; pass the resolved string to the
    // relevant SDK/client rather than storing it in a global.
    const dbUrl         = await getSecret('DATABASE_URL');
    const stripeKey     = await getSecret('STRIPE_SECRET_KEY');
    const anthropicKey  = await getSecret('ANTHROPIC_API_KEY');
    const logfireToken  = await getSecret('LOGFIRE_TOKEN');

    // --- Wire up services with the resolved secrets ---
    // (Placeholder comments show where real SDK initialisations would go.
    //  The actual secret strings are intentionally not logged or exported.)

    // e.g. await db.connect(dbUrl);
    console.info(`[app] Database target: ${new URL(dbUrl).host}`); // host only, no credentials

    // e.g. stripe = new Stripe(stripeKey);
    console.info(`[app] Stripe key loaded (length ${stripeKey.length}).`);

    // e.g. anthropic = new Anthropic({ apiKey: anthropicKey });
    console.info(`[app] Anthropic key loaded (length ${anthropicKey.length}).`);

    // e.g. logfire.configure({ token: logfireToken });
    console.info(`[app] Logfire token loaded (length ${logfireToken.length}).`);

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.info(`[app] Server running on port ${PORT}`);
    });
  } catch (err) {
    console.error('[app] Fatal: failed to load secrets at startup:', err.message);
    process.exit(1);
  }
}

// Only call start() when this file is run directly (not when required by
// tests, which manage their own lifecycle).
if (require.main === module) {
  start();
}

module.exports = { app, start };

