/**
 * secrets.js
 *
 * Centralised secret-access module.
 *
 * Resolution order
 * ────────────────
 * 1. AWS Secrets Manager  – always attempted first when NODE_ENV !== 'development'
 *    or when AWS_SECRETS_MANAGER_FORCE=true.
 * 2. Local .env.test fallback – used automatically in development, or whenever
 *    Secrets Manager is unreachable (with a console warning so the gap is
 *    visible in logs).
 *
 * The list of required secret names is derived exclusively from the keys that
 * are present in .env.test; no secret names (and certainly no secret values)
 * are hardcoded here.
 *
 * Usage
 * ────────────────
 *   const { getSecret, requiredSecrets } = require('./secrets');
 *
 *   const dbUrl = await getSecret('DATABASE_URL');
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test to discover the required secret NAMES.
//     Values read from this file are ONLY used as the dev/fallback source —
//     they are never forwarded to Secrets Manager or logged.
// ---------------------------------------------------------------------------
const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Minimal env-file parser (handles `KEY=value`, blank lines, and `# comments`).
 * Returns an object whose keys are variable names and values are variable values.
 * We intentionally avoid calling `dotenv.config()` globally so that secrets are
 * never silently injected into `process.env`.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Record<string, string>}
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`[secrets] Warning: env file not found at ${filePath}`);
    return {};
  }

  const lines  = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  const result = {};

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key   = line.slice(0, eqIdx).trim();
    // Strip optional surrounding quotes from the value
    const value = line.slice(eqIdx + 1).trim().replace(/^(['"])(.*)\1$/, '$2');

    if (key) result[key] = value;
  }

  return result;
}

// Parse once at module load.
const localSecrets = parseEnvFile(ENV_FILE);

/**
 * The authoritative list of secret names this application requires.
 * Derived solely from the keys present in .env.test.
 *
 * @type {string[]}
 */
const requiredSecrets = Object.keys(localSecrets);

// ---------------------------------------------------------------------------
// 2.  AWS Secrets Manager client (lazy-initialised).
// ---------------------------------------------------------------------------
let smClient = null; // initialised on first use

/**
 * Returns a memoised SecretsManagerClient.
 * We import the SDK lazily so that the module loads without error in
 * environments where the SDK is not yet installed (e.g. during unit tests
 * that mock the whole module).
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSmClient() {
  if (smClient) return smClient;

  // Lazy require — will throw a clear error if the package is missing.
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  smClient = new SecretsManagerClient({
    // Region is read from the standard AWS_REGION / AWS_DEFAULT_REGION env
    // vars or the shared config file — nothing is hardcoded here.
    region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION,
  });

  return smClient;
}

// In-process cache: secret name → resolved string value.
// Avoids repeated round-trips within the same process lifetime.
const cache = new Map();

// ---------------------------------------------------------------------------
// 3.  Core resolution logic.
// ---------------------------------------------------------------------------

/**
 * Determines whether Secrets Manager should be consulted.
 *
 *  • Always YES when AWS_SECRETS_MANAGER_FORCE=true (useful for integration tests).
 *  • YES when NODE_ENV is anything other than 'development'.
 *  • NO  in 'development' unless the above override is set.
 *
 * @returns {boolean}
 */
function shouldUseSm() {
  if (process.env.AWS_SECRETS_MANAGER_FORCE === 'true') return true;
  return process.env.NODE_ENV !== 'development';
}

/**
 * Fetches a secret string from AWS Secrets Manager.
 *
 * Secrets Manager stores each secret under its own name (e.g. "DATABASE_URL").
 * If the stored secret value is a JSON object the function looks for a key
 * matching `name` inside it, then falls back to the whole string value.
 *
 * @param {string} name  The secret name as it appears in Secrets Manager.
 * @returns {Promise<string>}
 * @throws  If the secret does not exist and has no local fallback.
 */
async function fetchFromSm(name) {
  const { GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

  const cmd      = new GetSecretValueCommand({ SecretId: name });
  const response = await getSmClient().send(cmd);
  const raw      = response.SecretString ?? '';

  // Support JSON-encoded secrets (e.g. {"DATABASE_URL":"postgres://…"}).
  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null && name in parsed) {
      return String(parsed[name]);
    }
    // JSON object but key not present — return the whole string so the caller
    // can decide what to do with it.
    return raw;
  } catch {
    // Not JSON — treat as a plain string value.
    return raw;
  }
}

// ---------------------------------------------------------------------------
// 4.  Public API.
// ---------------------------------------------------------------------------

/**
 * Retrieves the value for `name` using the resolution order described at the
 * top of this file.
 *
 * @param {string} name  Secret name (must match a key in .env.test).
 * @returns {Promise<string>}
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`[secrets] getSecret() requires a non-empty string name, got: ${name}`);
  }

  // Serve from in-process cache if available.
  if (cache.has(name)) {
    return cache.get(name);
  }

  // --- Attempt Secrets Manager ---
  if (shouldUseSm()) {
    try {
      const value = await fetchFromSm(name);
      cache.set(name, value);
      return value;
    } catch (err) {
      // Surface the specific AWS error class name for easier triage.
      const errLabel = err.name ?? err.constructor?.name ?? 'UnknownError';

      if (process.env.NODE_ENV !== 'test') {
        console.warn(
          `[secrets] Secrets Manager unavailable for "${name}" (${errLabel}). ` +
          `Falling back to local .env.test.`
        );
      }
      // Fall through to local fallback below.
    }
  }

  // --- Local .env.test fallback ---
  if (name in localSecrets) {
    const value = localSecrets[name];
    cache.set(name, value);
    return value;
  }

  throw new Error(
    `[secrets] Secret "${name}" not found in AWS Secrets Manager or local .env.test.`
  );
}

