 * Resolves all required secrets in parallel and returns them as a plain object.
 * Useful for bootstrapping — call once at startup and destructure what you need.
 *
 * @returns {Promise<Record<string, string>>}
 */
async function loadAllSecrets() {
  const entries = await Promise.all(
    requiredSecrets.map(async (name) => [name, await getSecret(name)])
  );
  return Object.fromEntries(entries);
}

/**
 * Clears the in-process secret cache.
 * Intended for use in tests that need fresh resolution on each run.
 */
function clearCache() {
  cache.clear();
}

module.exports = { getSecret, loadAllSecrets, clearCache, requiredSecrets };

/**
 * app.js
 *
 * All secrets are loaded via secrets.js, which reads names from .env.test and
 * resolves values from AWS Secrets Manager (with a local .env.test fallback in
 * development).  No secret values are hardcoded here.
 */

