{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with AWS Secrets Manager integration",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node --experimental-vm-modules node_modules/.bin/jest --forceExit"
  },
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "dotenv": "^16.0.0",
    "express": "^4.18.0"
  },
  "devDependencies": {
    "jest": "^29.0.0"
  }
}

/**
 * secrets.js — Centralised secret access layer.
 *
 * Resolution order
 * ────────────────
 * 1. AWS Secrets Manager  (always attempted first in every environment)
 * 2. Local .env.test file  (fallback, only when NODE_ENV !== 'production' AND
 *                           the Secrets Manager call fails or is unavailable)
 *
 * The module reads the *names* of required secrets from .env.test so that the
 * file acts purely as a schema/manifest — the values stored there are used
 * only as a last-resort local fallback and are never logged or exported
 * beyond the single call-site that requested them.
 *
 * IMPORTANT: Secret *values* are never logged, printed, added to error
 * messages, or attached to any object that leaves this module.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ── Configuration ────────────────────────────────────────────────────────────

const ENV_FILE        = path.resolve(__dirname, '.env.test');
const IS_PRODUCTION   = process.env.NODE_ENV === 'production';
const AWS_REGION      = process.env.AWS_REGION || 'us-east-1';

// ── Parse .env.test for secret *names* only ──────────────────────────────────

/**
 * Parses a .env file and returns an object whose keys are the variable names
 * and whose values are the raw strings from the file.
 *
 * This function is intentionally kept internal so callers never receive the
 * full map of values — they must go through getSecret() one name at a time.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {{ names: string[], _raw: Object }}
 *   `names`  – ordered list of every variable name declared in the file.
 *   `_raw`   – private map used only by the fallback path inside getSecret().
 *              Do NOT export or log this object.
 */
function _parseEnvFile(filePath) {
  const names = [];
  const _raw  = {};

  if (!fs.existsSync(filePath)) {
    return { names, _raw };
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const line of lines) {
    // Strip inline comments and surrounding whitespace.
    const stripped = line.replace(/#.*$/, '').trim();
    if (!stripped) continue;

    const eqIdx = stripped.indexOf('=');
    if (eqIdx === -1) continue;

    const name  = stripped.slice(0, eqIdx).trim();
    const value = stripped.slice(eqIdx + 1).trim();

    if (!name) continue;

    names.push(name);
    _raw[name] = value;
  }

  return { names, _raw };
}

// Parse once at module load time.
const { names: REQUIRED_SECRET_NAMES, _raw: _localFallback } = _parseEnvFile(ENV_FILE);

// ── AWS Secrets Manager client ───────────────────────────────────────────────

// Lazy-initialised so unit tests can stub the constructor before first use.
let _smClient = null;

function _getClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

/**
 * Replace the Secrets Manager client (used in tests / dependency injection).
 * @param {SecretsManagerClient} client
 */
function _setClient(client) {
  _smClient = client;
}

// ── Per-name in-process cache ─────────────────────────────────────────────────

/**
 * Simple TTL cache so repeated calls within the same process don't hammer
 * Secrets Manager.  Values are stored encrypted-at-rest in memory via a
 * trivial XOR obfuscation — this is not cryptographic security, it merely
 * prevents accidental secret exposure through heap dumps / core files that
 * record raw strings.
 *
 * Cache entries expire after CACHE_TTL_MS milliseconds.
 */
const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

const _cache = new Map(); // name → { obfuscated: Buffer, key: number, expiresAt: number }

/** Trivial XOR scramble — keeps secrets off the raw V8 string heap. */
function _obfuscate(plaintext) {
  const key    = Math.floor(Math.random() * 256);
  const buf    = Buffer.from(plaintext, 'utf8');
  const result = Buffer.alloc(buf.length);
  for (let i = 0; i < buf.length; i++) {
    result[i] = buf[i] ^ key;
  }
  return { obfuscated: result, key };
}

function _deobfuscate({ obfuscated, key }) {
  const result = Buffer.alloc(obfuscated.length);
  for (let i = 0; i < obfuscated.length; i++) {
    result[i] = obfuscated[i] ^ key;
  }
  return result.toString('utf8');
}

function _cacheGet(name) {
  const entry = _cache.get(name);
  if (!entry) return null;
  if (Date.now() > entry.expiresAt) {
    _cache.delete(name);
    return null;
  }
  return _deobfuscate(entry);
}

function _cacheSet(name, value) {
  const { obfuscated, key } = _obfuscate(value);
  _cache.set(name, { obfuscated, key, expiresAt: Date.now() + CACHE_TTL_MS });
}

// ── Core fetch logic ──────────────────────────────────────────────────────────

/**
 * Fetch a secret value from AWS Secrets Manager.
 *
 * Secrets Manager stores a secret identified by `name`; the returned payload
 * may be a plain string or a JSON object.  When it is JSON we look for a key
 * that matches `name`; otherwise we return the whole string value.
 *
 * @param {string} name  The secret name / ARN.
 * @returns {Promise<string>}
 * @throws  When the secret does not exist or the request fails.
 */
async function _fetchFromSecretsManager(name) {
  const client  = _getClient();
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);

  // Secrets Manager returns either SecretString or SecretBinary.
  if (response.SecretString !== undefined) {
    // Attempt to parse as JSON; fall back to raw string.
    try {
      const parsed = JSON.parse(response.SecretString);
      if (typeof parsed === 'object' && parsed !== null && name in parsed) {
        return String(parsed[name]);
      }
      // If the JSON key doesn't match `name`, return the whole string so the
      // caller can decide how to interpret it.
      return response.SecretString;
    } catch {
      return response.SecretString;
    }
  }

  if (response.SecretBinary) {
    // Binary secrets are returned as a Uint8Array; decode as UTF-8.
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`Secret "${name}" contained no readable value.`);
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Retrieve the value of a named secret.
 *
 * Resolution order:
 *   1. In-process cache (TTL: 5 min)
 *   2. AWS Secrets Manager
 *   3. Local .env.test fallback  (non-production only; logs a warning)
 *
 * @param {string} name  The secret name as it appears in .env.test /
 *                       Secrets Manager (e.g. "DATABASE_URL").
 * @returns {Promise<string>}
 * @throws  {Error} When the secret cannot be resolved from any source.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError('getSecret() requires a non-empty string name.');
  }

  // 1. In-process cache.
  const cached = _cacheGet(name);
  if (cached !== null) return cached;

  // 2. AWS Secrets Manager.
  try {
    const value = await _fetchFromSecretsManager(name);
    _cacheSet(name, value);
    return value;
  } catch (smError) {
    // Surface the error immediately in production — no fallback allowed.
    if (IS_PRODUCTION) {
      // Re-throw without the secret name in the message to avoid leaking info
      // through error telemetry, but include the original cause for operators.
      const err = new Error(
        `[secrets] Failed to fetch secret from Secrets Manager. ` +
        `Set AWS credentials / region and ensure the secret exists. ` +
        `Cause: ${smError.message}`
      );
      err.cause = smError;
      throw err;
    }

    // Non-production: warn and attempt local fallback.
    // We print the *name* only — never the value.
    console.warn(
      `[secrets] WARNING: Could not fetch "${name}" from Secrets Manager ` +
      `(${smError.message}). Falling back to .env.test. ` +
      `Do NOT use this fallback in production.`
    );
  }

  // 3. Local .env.test fallback (non-production only).
  if (name in _localFallback) {
    const value = _localFallback[name];
    _cacheSet(name, value);
    return value;
  }

  throw new Error(
    `[secrets] Secret "${name}" not found in Secrets Manager or .env.test.`
  );
}

/**
 * The ordered list of secret names declared in .env.test.
 * Useful for startup validation — call getSecret() for each name to confirm
 * all secrets are resolvable before accepting traffic.
 *
 * @type {string[]}
 */
const requiredSecretNames = Object.freeze([...REQUIRED_SECRET_NAMES]);

/**
 * Resolve every required secret and throw if any are missing.
 * Call this once at application startup (before binding to a port).
 *
 * @returns {Promise<void>}
 */
async function validateRequiredSecrets() {
  const errors = [];

  await Promise.all(
    requiredSecretNames.map(async (name) => {
      try {
        await getSecret(name);
      } catch (err) {
        // Collect the name of the missing secret, not its value.
        errors.push(`  • ${name}: ${err.message}`);
      }
    })
  );

  if (errors.length > 0) {
    throw new Error(
      `[secrets] The following required secrets could not be resolved:\n` +
      errors.join('\n')
    );
  }
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  getSecret,
  requiredSecretNames,
  validateRequiredSecrets,

  // Internal helpers exposed for testing only — not part of the public API.
  _setClient,
  _clearCache: () => _cache.clear(),
};

/**
 * app.js — Express application entry point.
 *
 * Secrets are never loaded from environment variables directly.  All access
 * goes through secrets.js, which resolves values from AWS Secrets Manager
 * (with a local .env.test fallback in non-production environments).
 */

'use strict';

const express = require('express');
const { getSecret, validateRequiredSecrets } = require('./secrets');

const app = express();
app.use(express.json());

// ── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/**
 * Example of a route that consumes a secret at request time.
 *
 * getSecret() is async and cached in-process, so calling it per-request is
 * safe — it only hits Secrets Manager on the first call (or after TTL expiry).
 *
 * The resolved value is used internally and NEVER sent to the client.
 */
app.get('/db-status', async (req, res) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');

    // Use the secret internally (e.g. test connectivity) — do not echo it back.
    // Here we simply confirm it was resolved without exposing the value.
    const isResolved = typeof dbUrl === 'string' && dbUrl.length > 0;

    res.json({ database: isResolved ? 'reachable' : 'unavailable' });
  } catch (err) {
    // Return a generic error; never include err.message in the response body
    // because it may contain secret names or infrastructure details.
    console.error('[app] /db-status error:', err.message);
    res.status(503).json({ error: 'Service temporarily unavailable.' });
  }
});

// ── Startup ───────────────────────────────────────────────────────────────────

/**
 * start() validates that every secret listed in .env.test can be resolved
 * before the server begins accepting connections.  This surfaces
 * misconfiguration (missing IAM permissions, wrong secret names, etc.) at
 * boot time rather than at the moment a request first needs a secret.
 */
async function start() {
  await validateRequiredSecrets();
  return new Promise((resolve) => {
    const server = app.listen(3000, () => {
      console.log('Server running on port 3000');
      resolve(server);
    });
  });
}

// Only auto-start when this file is run directly, not when required by tests.
if (require.main === module) {
  start().catch((err) => {
    console.error('[app] Startup failed:', err.message);
    process.exit(1);
  });
}

module.exports = { app, start };

/**
 * secrets.test.js
 *
 * Tests for secrets.js.  All tests use a stub Secrets Manager client so no
 * real AWS calls are made and no real secret values are ever used.
 */

'use strict';

const {
  getSecret,
  requiredSecretNames,
  validateRequiredSecrets,
  _setClient,
  _clearCache,
} = require('./secrets');

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Build a minimal stub SecretsManagerClient. */
function makeStubClient({ secretString, binary, error } = {}) {
  return {
    send: jest.fn(async (command) => {
      if (error) throw error;
      if (binary) return { SecretBinary: Buffer.from(binary, 'utf8') };
      return { SecretString: secretString ?? '' };
    }),
  };
}

beforeEach(() => {
  _clearCache();
  // Reset NODE_ENV for each test unless the test overrides it.
  process.env.NODE_ENV = 'test';
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ── requiredSecretNames ───────────────────────────────────────────────────────

describe('requiredSecretNames', () => {
  test('is a non-empty frozen array', () => {
    expect(Array.isArray(requiredSecretNames)).toBe(true);
    expect(requiredSecretNames.length).toBeGreaterThan(0);
    expect(Object.isFrozen(requiredSecretNames)).toBe(true);
  });

  test('contains the names declared in .env.test (no values)', () => {
    // Only check names — never assert specific values.
    const expected = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
    ];
    expect(requiredSecretNames).toEqual(expected);
  });

  test('does not expose secret values', () => {
    // requiredSecretNames must be an array of strings (names), not a map.
    for (const entry of requiredSecretNames) {
      expect(typeof entry).toBe('string');
      // A name should not contain '=' (which would mean a full KEY=VALUE line
      // was accidentally included).
      expect(entry).not.toContain('=');
    }
  });
});

// ── getSecret — Secrets Manager happy path ────────────────────────────────────

describe('getSecret() — Secrets Manager success', () => {
  test('returns the SecretString value', async () => {
    const stub = makeStubClient({ secretString: 'resolved-value' });
    _setClient(stub);

    const value = await getSecret('DATABASE_URL');
    expect(value).toBe('resolved-value');
    expect(stub.send).toHaveBeenCalledTimes(1);
  });

  test('parses JSON SecretString and returns matching key', async () => {
    const payload = JSON.stringify({ DATABASE_URL: 'json-db-value' });
    const stub = makeStubClient({ secretString: payload });
    _setClient(stub);

    const value = await getSecret('DATABASE_URL');
    expect(value).toBe('json-db-value');
  });

  test('returns full JSON string when name is not a key in the JSON', async () => {
    const payload = JSON.stringify({ some_other_key: 'val' });
    const stub = makeStubClient({ secretString: payload });
    _setClient(stub);

    const value = await getSecret('DATABASE_URL');
    // Falls back to the whole SecretString since 'DATABASE_URL' ∉ JSON keys.
    expect(value).toBe(payload);
  });

  test('decodes SecretBinary value', async () => {
    const stub = makeStubClient({ binary: 'binary-secret' });
    _setClient(stub);

    const value = await getSecret('DATABASE_URL');
    expect(value).toBe('binary-secret');
  });
});

// ── getSecret — caching ───────────────────────────────────────────────────────

describe('getSecret() — in-process caching', () => {
  test('only calls Secrets Manager once for repeated requests', async () => {
    const stub = makeStubClient({ secretString: 'cached-value' });
    _setClient(stub);

    await getSecret('DATABASE_URL');
    await getSecret('DATABASE_URL');
    await getSecret('DATABASE_URL');

    expect(stub.send).toHaveBeenCalledTimes(1);
  });

  test('fetches again after cache is cleared', async () => {
    const stub = makeStubClient({ secretString: 'fresh-value' });
    _setClient(stub);

    await getSecret('DATABASE_URL');
    _clearCache();
    await getSecret('DATABASE_URL');

    expect(stub.send).toHaveBeenCalledTimes(2);
  });

  test('different secret names are cached independently', async () => {
    const stub = makeStubClient({ secretString: 'some-value' });
    _setClient(stub);

    await getSecret('DATABASE_URL');
    await getSecret('STRIPE_SECRET_KEY');
    await getSecret('DATABASE_URL');   // should hit cache

    expect(stub.send).toHaveBeenCalledTimes(2);
  });
});

// ── getSecret — local fallback ────────────────────────────────────────────────

describe('getSecret() — .env.test local fallback', () => {
  test('falls back to .env.test in non-production when SM fails', async () => {
    const stub = makeStubClient({ error: new Error('EndpointResolutionError') });
    _setClient(stub);
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    // The fallback value comes from .env.test — we don't assert its content,
    // only that *something* was returned (truthy string).
    const value = await getSecret('DATABASE_URL');
    expect(typeof value).toBe('string');
    expect(value.length).toBeGreaterThan(0);
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('Falling back to .env.test')
    );
  });

  test('warning message contains the secret name but not a secret value', async () => {
    const stub = makeStubClient({ error: new Error('network failure') });
    _setClient(stub);
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    await getSecret('STRIPE_SECRET_KEY');

    const warnArg = warnSpy.mock.calls[0][0];
    expect(warnArg).toContain('STRIPE_SECRET_KEY');
    // The warning must NOT contain any of the actual values from .env.test.
    // We verify this structurally: the message should only contain the name,
    // the error text, and our static template strings.
    expect(warnArg).not.toContain('postgres://');
    expect(warnArg).not.toContain('sk_live');
    expect(warnArg).not.toContain('sk-ant');
  });

  test('throws when secret not in .env.test either', async () => {
    const stub = makeStubClient({ error: new Error('not found') });
    _setClient(stub);
    jest.spyOn(console, 'warn').mockImplementation(() => {});

    await expect(getSecret('NONEXISTENT_SECRET')).rejects.toThrow(
      'NONEXISTENT_SECRET'
    );
  });

  test('throws immediately in production without consulting .env.test', async () => {
    process.env.NODE_ENV = 'production';
    const stub = makeStubClient({ error: new Error('AccessDeniedException') });
    _setClient(stub);
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    await expect(getSecret('DATABASE_URL')).rejects.toThrow(
      /Failed to fetch secret from Secrets Manager/
    );
    expect(warnSpy).not.toHaveBeenCalled();

    process.env.NODE_ENV = 'test';
  });
});

// ── getSecret — input validation ──────────────────────────────────────────────

describe('getSecret() — input validation', () => {
  test('throws TypeError for empty string', async () => {
    await expect(getSecret('')).rejects.toThrow(TypeError);
  });

  test('throws TypeError for non-string input', async () => {
    await expect(getSecret(null)).rejects.toThrow(TypeError);
    await expect(getSecret(42)).rejects.toThrow(TypeError);
    await expect(getSecret()).rejects.toThrow(TypeError);
  });
});

// ── validateRequiredSecrets ───────────────────────────────────────────────────

describe('validateRequiredSecrets()', () => {
  test('resolves when all secrets are available', async () => {
    const stub = makeStubClient({ secretString: 'ok' });
    _setClient(stub);

    await expect(validateRequiredSecrets()).resolves.toBeUndefined();
  });

  test('rejects with a list of missing names when SM fails and no fallback', async () => {
    // Override the env to production so the fallback is disabled.
    process.env.NODE_ENV = 'production';
    const stub = makeStubClient({ error: new Error('AccessDeniedException') });
    _setClient(stub);

    await expect(validateRequiredSecrets()).rejects.toThrow(
      /could not be resolved/
    );

    process.env.NODE_ENV = 'test';
  });

  test('error message contains secret names, not secret values', async () => {
    process.env.NODE_ENV = 'production';
    const stub = makeStubClient({ error: new Error('AccessDeniedException') });
    _setClient(stub);

    let caughtMessage = '';
    try {
      await validateRequiredSecrets();
    } catch (err) {
      caughtMessage = err.message;
    }

    // Names should appear so the operator knows what to fix.
    expect(caughtMessage).toContain('DATABASE_URL');

    // Values must never appear in error messages.
    expect(caughtMessage).not.toContain('postgres://');
    expect(caughtMessage).not.toContain('REDACTED_AWS_AKID');
    expect(caughtMessage).not.toContain('sk-ant');
    expect(caughtMessage).not.toContain('sk_live');

    process.env.NODE_ENV = 'test';
  });
});

