/**
 * secrets.js
 *
 * Centralised secret-fetching module.
 *
 * Strategy
 * --------
 *  1. On start-up, parse .env.test with dotenv to discover which secret
 *     names the application needs (keys only — values are never used
 *     outside a local-dev fallback).
 *  2. getSecret(name) tries AWS Secrets Manager first.
 *  3. If Secrets Manager is unavailable AND NODE_ENV is "development",
 *     the function falls back to the value from .env.test so local
 *     development still works without AWS credentials.
 *  4. In any other environment the function throws, keeping production
 *     safe from silent fallback to local files.
 *
 * AWS authentication is handled entirely by the SDK's default credential
 * provider chain (env vars, ~/.aws/credentials, IAM role, etc.).
 * No credentials are hardcoded here.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const {
  SecretsManagerClient,
  GetSecretValueCommand,
} = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to obtain the list of required secret names.
//    We only read the *keys*; we never expose the values at module scope.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parse a dotenv-formatted file and return { key → raw-line-value } map.
 * This avoids pulling in dotenv just for key discovery and keeps the
 * parsing logic transparent.
 *
 * Rules:
 *  - Lines starting with # are comments.
 *  - Blank lines are ignored.
 *  - KEY=VALUE  (VALUE may be quoted or unquoted).
 *  - Inline comments (# …) after a value are stripped.
 *
 * @param {string} filePath  Absolute path to the env file.
 * @returns {Map<string, string>}  key → value
 */
function parseDotenv(filePath) {
  const entries = new Map();

  if (!fs.existsSync(filePath)) {
    return entries; // tolerate a missing file; caller decides what to do
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue; // malformed line — skip silently

    const key = line.slice(0, eqIdx).trim();

    // Strip optional surrounding quotes, then inline comments
    let value = line.slice(eqIdx + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    } else {
      // Remove inline comment (space + # …)
      value = value.replace(/\s+#.*$/, '');
    }

    if (key) entries.set(key, value);
  }

  return entries;
}

// Build the set of expected secret names from .env.test
const _envFileEntries = parseDotenv(ENV_FILE);

/** Immutable list of secret names the application is expected to use. */
const REQUIRED_SECRET_NAMES = Object.freeze([..._envFileEntries.keys()]);

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client
// ---------------------------------------------------------------------------

/**
 * Lazily constructed Secrets Manager client so that tests or scripts that
 * never call getSecret() don't pay the SDK initialisation cost.
 * The region is read from AWS_REGION / AWS_DEFAULT_REGION env vars (standard
 * AWS SDK convention) or falls back to 'us-east-1'.
 */
let _smClient = null;
function _getClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

// Per-process in-memory cache so each secret is fetched at most once per
// process lifetime.  Values are stored encrypted-at-rest in Secrets Manager;
// this cache is just a network-efficiency measure.
const _cache = new Map();

// ---------------------------------------------------------------------------
// 3. getSecret(name)
// ---------------------------------------------------------------------------

/**
 * Fetch a secret value by name.
 *
 * Lookup order:
 *  a) In-memory cache (populated on first fetch).
 *  b) AWS Secrets Manager.
 *  c) .env.test fallback — only when NODE_ENV === 'development'.
 *
 * @param {string} name  The secret name (must be one of REQUIRED_SECRET_NAMES).
 * @returns {Promise<string>}  The plaintext secret value.
 * @throws  If the secret cannot be resolved in the current environment.
 */
async function getSecret(name) {
  if (!name || typeof name !== 'string') {
    throw new TypeError(`getSecret: 'name' must be a non-empty string, got ${JSON.stringify(name)}`);
  }

  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    // Warn but don't hard-block — the caller may request a secret that was
    // added after the last .env.test refresh.
    console.warn(`[secrets] Warning: "${name}" is not listed in .env.test`);
  }

  // (a) Return from cache if available
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  // (b) Try Secrets Manager
  try {
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await _getClient().send(command);

    // Secrets Manager returns either SecretString or SecretBinary
    const value = response.SecretString
      ?? Buffer.from(response.SecretBinary).toString('utf8');

    _cache.set(name, value);
    return value;
  } catch (smError) {
    // Only fall back to .env.test in development; in all other environments
    // we surface the real error so on-call engineers know something is wrong.
    if (process.env.NODE_ENV === 'development') {
      if (_envFileEntries.has(name)) {
        console.warn(
          `[secrets] Secrets Manager unavailable for "${name}" — ` +
          `using .env.test fallback (NODE_ENV=development). ` +
          `SM error: ${smError.message}`
        );
        const fallback = _envFileEntries.get(name);
        _cache.set(name, fallback);
        return fallback;
      }
      throw new Error(
        `[secrets] Secret "${name}" not found in Secrets Manager ` +
        `and has no .env.test fallback. SM error: ${smError.message}`
      );
    }

    // Non-development: propagate the original error
    throw new Error(
      `[secrets] Failed to retrieve secret "${name}" from Secrets Manager: ${smError.message}`
    );
  }
}

