// 4. Exports
// ---------------------------------------------------------------------------

module.exports = {
  /**
   * Fetch a secret by name.
   * @type {(name: string) => Promise<string>}
   */
  getSecret,

  /**
   * The list of secret names discovered from .env.test.
   * Useful for prefetch / warm-up at application start.
   * @type {ReadonlyArray<string>}
