  const secrets = await loadSecrets(); // throws on any unresolved secret

  // Attach secrets to app.locals so route handlers can access them via
  // req.app.locals.secrets.  This is preferable to a module-level variable
  // because it keeps the secrets scoped to this specific Express instance
  // (important in test environments where multiple app instances may coexist).
