// ── inline smoke-test ──────────────────────────────────────────────────────
// Stub the SDK module so we can test secrets.js without installing packages.
// We exercise: parseDotenv, REQUIRED_SECRET_NAMES, SM error → dev fallback,
// SM error → non-dev throw, and the in-memory cache.

'use strict';

const Module = require('module');
const originalLoad = Module._load;

// Intercept require('@aws-sdk/client-secrets-manager')
Module._load = function(request, ...rest) {
  if (request === '@aws-sdk/client-secrets-manager') {
    let _shouldFail = true;
    return {
      SecretsManagerClient: class {
        send() {
          if (_shouldFail) return Promise.reject(new Error('SM_UNAVAILABLE'));
          return Promise.resolve({ SecretString: 'sm-live-value' });
        }
        // expose a toggle for the "success" path test
        static setFail(v) { _shouldFail = v; }
      },
      GetSecretValueCommand: class { constructor(p) { this.params = p; } },
      _setFail(v) { _shouldFail = v; },
    };
  }
  return originalLoad.call(this, request, ...rest);
};

// ── helpers ────────────────────────────────────────────────────────────────
let passed = 0;
let failed = 0;
function assert(condition, label) {
  if (condition) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    failed++;
  }
}

async function run() {
