    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
  ];
  assert(REQUIRED_SECRET_NAMES.length === expected.length,
    `Found ${REQUIRED_SECRET_NAMES.length} names`);
  for (const name of expected) {
    assert(REQUIRED_SECRET_NAMES.includes(name), `Includes "${name}"`);
  }

  // ── Test 2: dev fallback when SM fails ──────────────────────────────────
  console.log('\n[2] dev fallback (SM unavailable)');
  process.env.NODE_ENV = 'development';
  const val = await getSecret('STRIPE_SECRET_KEY');
  assert(typeof val === 'string' && val.length > 0,
    'Returns a non-empty string from .env.test fallback');
  // Must NOT be hard-coded here — just check it matches what parseDotenv read
  assert(val === val.trim(), 'Value has no surrounding whitespace');

  // ── Test 3: in-memory cache ──────────────────────────────────────────────
  console.log('\n[3] In-memory cache');
  const val2 = await getSecret('STRIPE_SECRET_KEY');
  assert(val === val2, 'Second call returns cached value');

  // ── Test 4: non-dev throws on SM failure ────────────────────────────────
  console.log('\n[4] Non-dev throws when SM unavailable');
  // Need a fresh module instance with a clean cache for a different key
  // We can't easily re-require (cache), so test with a known-missing key.
  // Instead flip NODE_ENV and try a key that is NOT in the module cache yet.
  // Use a key that definitely hasn't been fetched: AWS_ACCESS_KEY_ID
  process.env.NODE_ENV = 'production';
  try {
    await getSecret('AWS_ACCESS_KEY_ID');
    assert(false, 'Should have thrown in production');
  } catch (err) {
    assert(err.message.includes('Failed to retrieve secret'), `Throws: ${err.message}`);
  }

  // ── Test 5: TypeError for bad input ─────────────────────────────────────
  console.log('\n[5] TypeError for invalid argument');
  try {
    await getSecret(null);
    assert(false, 'Should throw TypeError');
  } catch (err) {
    assert(err instanceof TypeError, `Throws TypeError: ${err.message}`);
  }

  // ── Summary ───────────────────────────────────────────────────────────────
  console.log(`\n${'─'.repeat(50)}`);
  console.log(`Results: ${passed} passed, ${failed} failed`);
  process.exit(failed > 0 ? 1 : 0);
}

