// ---------------------------------------------------------------------------
// 1. Parse .env.test to obtain the list of required secret names.
//    We only read the *keys*; we never expose the values at module scope.
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Parse a dotenv-formatted file and return { key → raw-line-value } map.
 * This avoids pulling in dotenv just for key discovery and keeps the
 * parsing logic transparent.
 *
 * Rules:
 *  - Lines starting with # are comments.
 *  - Blank lines are ignored.
 *  - KEY=VALUE  (VALUE may be quoted or unquoted).
 *  - Inline comments (# …) after a value are stripped.
 *
 * @param {string} filePath  Absolute path to the env file.
 * @returns {Map<string, string>}  key → value
 */
function parseDotenv(filePath) {
  const entries = new Map();

  if (!fs.existsSync(filePath)) {
    return entries; // tolerate a missing file; caller decides what to do
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue; // malformed line — skip silently

    const key = line.slice(0, eqIdx).trim();

    // Strip optional surrounding quotes, then inline comments
    let value = line.slice(eqIdx + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    } else {
      // Remove inline comment (space + # …)
      value = value.replace(/\s+#.*$/, '');
    }

    if (key) entries.set(key, value);
  }

  return entries;
}

// Build the set of expected secret names from .env.test
const _envFileEntries = parseDotenv(ENV_FILE);

/** Immutable list of secret names the application is expected to use. */
const REQUIRED_SECRET_NAMES = Object.freeze([..._envFileEntries.keys()]);

