 * AWS SDK convention) or falls back to 'us-east-1'.
 */
let _smClient = null;
function _getClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({
      region: process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1',
    });
  }
  return _smClient;
}

