// process lifetime.  Values are stored encrypted-at-rest in Secrets Manager;
// this cache is just a network-efficiency measure.
const _cache = new Map();

// ---------------------------------------------------------------------------
// 3. getSecret(name)
// ---------------------------------------------------------------------------

/**
 * Fetch a secret value by name.
 *
 * Lookup order:
 *  a) In-memory cache (populated on first fetch).
 *  b) AWS Secrets Manager.
 *  c) .env.test fallback — only when NODE_ENV === 'development'.
