 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * 1. At startup, parse .env.test with dotenv (values-only ignored; we use the
 *    file solely to discover *which* secret names the application needs).
 * 2. getSecret(name) tries AWS Secrets Manager first.
 *    • In production (NODE_ENV=production) a missing Secrets Manager value is
 *      a hard error – no plaintext fallback is allowed.
 *    • In every other environment (development, test, CI …) a failed AWS call
 *      falls back to the value dotenv loaded from .env.test, enabling offline
 *      development without real AWS credentials.
 * 3. No secret value is ever hard-coded in this file.
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1. Parse .env.test to discover required secret names
// ---------------------------------------------------------------------------

const ENV_FILE = path.resolve(__dirname, '.env.test');

/**
 * Read .env.test and return a Set of the variable names declared in it.
 * Values are intentionally discarded here; they are re-loaded by dotenv
 * into process.env only for the fallback path below.
 *
 * @returns {Set<string>}
 */
function parseEnvFileKeys(filePath) {
  if (!fs.existsSync(filePath)) {
    console.warn(`[secrets] .env.test not found at ${filePath}; no keys registered.`);
    return new Set();
  }

  const lines = fs.readFileSync(filePath, 'utf8').split('\n');
  const keys  = new Set();

  for (const raw of lines) {
    const line = raw.trim();
    // Skip blank lines and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx < 1) continue;        // malformed line – no key before '='

    const key = line.slice(0, eqIdx).trim();
    if (key) keys.add(key);
  }

  return keys;
}

/** Names that must be resolvable at runtime. */
const REQUIRED_SECRET_NAMES = parseEnvFileKeys(ENV_FILE);

// Load .env.test into process.env so the fallback path can read values from it.
// dotenv.config is intentionally called *after* we have already captured the
// key names so the two concerns stay clearly separated.
