  // fallback behaviour) even if the package is not yet installed.
  const dotenv = require('dotenv');
  dotenv.config({ path: ENV_FILE });
} catch (err) {
  console.warn('[secrets] dotenv not available; local fallback values will not be loaded.', err.message);
}

// ---------------------------------------------------------------------------
// 2. AWS Secrets Manager client (created lazily on first use)
// ---------------------------------------------------------------------------

let _smClient = null;

/**
 * Return a (cached) SecretsManagerClient.
 * The client is built lazily so that environments without the AWS SDK
 * (e.g. a stripped-down Docker layer that injects secrets differently)
 * do not fail at module-load time.
 *
 * @returns {import('@aws-sdk/client-secrets-manager').SecretsManagerClient}
 */
function getSmClient() {
  if (_smClient) return _smClient;

  // Will throw if the package is not installed – caller handles the error.
  const { SecretsManagerClient } = require('@aws-sdk/client-secrets-manager');

  // Credentials and region are resolved by the SDK's default credential chain:
  //   IAM role → ECS task role → environment variables → ~/.aws/credentials
