// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

init()
  .then(() => {
    app.listen(3000, () => {
      console.log('[app] Server running on port 3000');
    });
  })
  .catch((err) => {
    console.error('[app] Startup failed – aborting:', err.message);
    process.exit(1);
  });

module.exports = app;

