 * Lines that are blank or start with '#' are ignored.
 *
 * @returns {string[]}  e.g. ['DATABASE_URL', 'STRIPE_SECRET_KEY', ...]
 */
function loadRequiredSecretNames() {
  const envFilePath = path.resolve(__dirname, '.env.test');

  if (!fs.existsSync(envFilePath)) {
    console.warn('[secrets] .env.test not found – no required secret names loaded.');
    return [];
  }

  const lines = fs.readFileSync(envFilePath, 'utf8').split('\n');

  return lines.reduce((names, line) => {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) return names;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return names;

    const key = trimmed.slice(0, eqIndex).trim();
    if (key) names.push(key);
    return names;
  }, []);
}

