    "express": "^4.19.2"
  }
}

/**
 * secrets.js — Centralised secret resolution module.
 *
 * Strategy
 * ────────
 * 1. At startup, parse .env.test with dotenv to discover the *names* of every
 *    required secret (the keys).  The values loaded from the file are only
 *    used as a local fallback (see point 3 below).
 * 2. In production / staging (NODE_ENV !== 'development') every call to
 *    getSecret(name) fetches the secret value from AWS Secrets Manager.
 * 3. In development (NODE_ENV === 'development') the value from .env.test is
 *    returned without making a network call, so developers can work offline
 *    without real AWS credentials.
 *
 * No secret value is ever hard-coded in this file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ─── Configuration ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const IS_DEV       = process.env.NODE_ENV === 'development';

// AWS region is read from the environment; falls back to us-east-1.
const AWS_REGION   = process.env.AWS_REGION || 'us-east-1';

// ─── Parse .env.test to discover required secret names ───────────────────────

/**
 * Parses a .env file and returns a plain object of { KEY: 'value', … }.
 * Handles:
 *   - blank lines and comment lines beginning with #
 *   - optional surrounding quotes on values
 *   - inline comments after a value (e.g. KEY=value  # note)
 *
 * This intentionally uses a small hand-rolled parser rather than loading
 * dotenv into `process.env` globally, so that secret *values* never leak
 * into the process environment in production builds.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const entries = {};
  const raw = fs.readFileSync(filePath, 'utf8');

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and full-line comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const key = trimmed.slice(0, eqIdx).trim();
    if (!key) continue;

    // Strip optional surrounding single or double quotes, and inline comments.
    let value = trimmed.slice(eqIdx + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    } else {
      // Remove inline comment (unquoted values only).
      const commentIdx = value.indexOf(' #');
      if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
    }

    entries[key] = value;
  }

  return entries;
}

// `localSecrets` holds the key→value pairs from .env.test.
// In production this object is used ONLY to enumerate the required key names
// (not to serve values). In development it doubles as the value store.
const localSecrets = parseEnvFile(ENV_FILE);

/** Sorted list of secret names that the application requires. */
const REQUIRED_SECRET_NAMES = Object.keys(localSecrets).sort();

if (REQUIRED_SECRET_NAMES.length === 0) {
  console.warn('[secrets] Warning: no secret names found in', ENV_FILE);
} else {
  console.info('[secrets] Required secrets:', REQUIRED_SECRET_NAMES.join(', '));
  console.info('[secrets] Mode:', IS_DEV ? 'development (local fallback)' : 'production (AWS Secrets Manager)');
}

// ─── AWS Secrets Manager client ──────────────────────────────────────────────

// Lazily created so that the module can be imported in development without
// valid AWS credentials present.
let _smClient = null;

function getSmClient() {
  if (!_smClient) {
    _smClient = new SecretsManagerClient({ region: AWS_REGION });
  }
  return _smClient;
}

// ─── In-process cache ─────────────────────────────────────────────────────────

// Caches resolved values for the lifetime of the process to avoid hammering
// Secrets Manager on every request.  Keys are secret names.
const _cache = new Map();

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Fetches the value for `name` from AWS Secrets Manager.
 *
 * Secrets Manager can store secrets as either a plain string or a JSON
 * object.  This function returns the raw string for plain secrets, or the
 * entire JSON-parsed object for JSON secrets (callers may then access
 * individual fields).
 *
 * Throws if the secret cannot be retrieved.
 *
 * @param {string} name - The secret name / ARN as stored in Secrets Manager.
 * @returns {Promise<string|object>}
 */
async function fetchFromSecretsManager(name) {
  const client  = getSmClient();
  const command = new GetSecretValueCommand({ SecretId: name });
  const response = await client.send(command);

  if (response.SecretString !== undefined) {
    // Try to parse as JSON; return the raw string if it is not valid JSON.
    try {
      return JSON.parse(response.SecretString);
    } catch {
      return response.SecretString;
    }
  }

  if (response.SecretBinary) {
    // Binary secrets are returned as a Uint8Array; decode to UTF-8 string.
    return Buffer.from(response.SecretBinary).toString('utf8');
  }

  throw new Error(`[secrets] Secret "${name}" has neither SecretString nor SecretBinary`);
