/**
 * Resolves the value of a secret by name.
 *
 * • In **development** (`NODE_ENV=development`): returns the value from the
 *   local .env.test file without contacting AWS.
 * • In **all other environments**: fetches from AWS Secrets Manager and caches
 *   the result in-process for the lifetime of the Node process.
 *
 * @param {string} name - Secret name, must match a key in .env.test (which
 *                        defines the canonical list of required secrets).
 * @returns {Promise<string|object>} Resolved secret value.
 * @throws {Error} If the name is not in the required-secrets list, or if the
 *                 AWS call fails.
 */
async function getSecret(name) {
  if (!REQUIRED_SECRET_NAMES.includes(name)) {
    throw new Error(
      `[secrets] Unknown secret "${name}". ` +
      `Required secrets are: ${REQUIRED_SECRET_NAMES.join(', ')}`
    );
  }

  // ── Development: use local file value ──────────────────────────────────────
  if (IS_DEV) {
    const value = localSecrets[name];
    if (value === undefined) {
      throw new Error(`[secrets] Secret "${name}" not found in ${ENV_FILE}`);
    }
    return value;
  }

  // ── Production: check cache first, then Secrets Manager ────────────────────
  if (_cache.has(name)) {
    return _cache.get(name);
  }

  const value = await fetchFromSecretsManager(name);
  _cache.set(name, value);
  return value;
}

/**
 * Pre-warms the in-process cache by fetching all required secrets from
 * Secrets Manager in parallel.  Call this once during application startup
 * (before the server begins accepting traffic) to surface misconfiguration
 * early and avoid cold-start latency on the first real request.
 *
 * Safe to call in development — it simply resolves all values from the local
 * file without making any network calls.
 *
 * @returns {Promise<void>}
 */
async function loadAllSecrets() {
  await Promise.all(REQUIRED_SECRET_NAMES.map((name) => getSecret(name)));
  console.info('[secrets] All secrets loaded successfully.');
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  /** Sorted array of secret names derived from .env.test */
  REQUIRED_SECRET_NAMES,
  /** Fetch a single secret by name (cached after first call in production). */
  getSecret,
  /** Pre-warm the cache for all required secrets at startup. */
  loadAllSecrets,
};

'use strict';

/**
 * app.js — Express application entry point.
 *
 * Secrets are never accessed directly from process.env or hard-coded.
 * All secret values are resolved through secrets.js, which handles
 * the AWS Secrets Manager / local-fallback strategy transparently.
 */

const express               = require('express');
const { getSecret, loadAllSecrets } = require('./secrets');

const app = express();
app.use(express.json());

// ─── Routes ───────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * GET /config-check
 *
 * Diagnostic endpoint that verifies every required secret can be resolved.
 * Returns the secret *names* and whether each resolved successfully — never
 * the secret values themselves.
 */
app.get('/config-check', async (req, res) => {
  const { REQUIRED_SECRET_NAMES } = require('./secrets');
  const results = await Promise.allSettled(
    REQUIRED_SECRET_NAMES.map(async (name) => {
      await getSecret(name);
      return name;
    })
  );

  const report = results.map((r, i) => ({
    name   : REQUIRED_SECRET_NAMES[i],
    status : r.status,               // 'fulfilled' | 'rejected'
    ...(r.status === 'rejected' && { error: r.reason?.message }),
  }));

  const allOk = report.every((r) => r.status === 'fulfilled');
  res.status(allOk ? 200 : 500).json({ ok: allOk, secrets: report });
});

// ─── Example: using a secret inside a route handler ───────────────────────────

/**
 * GET /db-status
 *
 * Demonstrates fetching a secret on demand inside a route.
 * The DATABASE_URL value is retrieved (and cached after the first call)
 * from Secrets Manager in production, or from .env.test in development.
 */
app.get('/db-status', async (req, res) => {
  try {
    const dbUrl = await getSecret('DATABASE_URL');

    // Use only the non-sensitive parts of the URL for the response.
    const { hostname, port, pathname } = new URL(dbUrl);
    res.json({ connected: true, host: hostname, port, database: pathname.replace('/', '') });
  } catch (err) {
    console.error('[app] Failed to retrieve DATABASE_URL:', err.message);
    res.status(500).json({ connected: false, error: 'Could not resolve database configuration.' });
  }
});

// ─── Startup ──────────────────────────────────────────────────────────────────

/**
 * Pre-warm the secrets cache before accepting traffic.
 * Any misconfigured or missing secret will abort startup with a clear error
 * rather than failing silently on the first real request.
 */
async function start() {
  try {
    await loadAllSecrets();
  } catch (err) {
    console.error('[app] Startup aborted — failed to load secrets:', err.message);
    process.exit(1);
  }

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

// Only call start() when this file is executed directly (not when required by
// tests), so that test suites can import `app` without binding a port.
if (require.main === module) {
  start();
}

module.exports = app;

