/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Strategy
 * --------
 * 1. On startup, parse .env.test with dotenv (path is configurable via
 *    ENV_FILE env var) to discover which secret *names* are required.
 *    The values from that file are kept in memory only as a local fallback;
 *    they are never logged or re-exported.
 *
 * 2. getSecret(name) tries AWS Secrets Manager first (when
 *    NODE_ENV !== 'development' OR when AWS_REGION is explicitly set).
 *    On any AWS error, or when running locally without AWS credentials,
 *    it falls back to the value from the local env file.
 *
 * 3. The module validates on initialisation that every name found in the
 *    env file can actually be resolved, so missing secrets fail fast at
 *    startup rather than at the point of use.
 *
 * Environment variables that control behaviour (none are secrets):
 *   AWS_REGION     – AWS region for Secrets Manager (default: us-east-1)
 *   AWS_SM_PREFIX  – optional path prefix, e.g. "myapp/prod/"
 *                    secrets are looked up as "<prefix><name>"
 *   ENV_FILE       – path to the local env file (default: .env.test)
 *   NODE_ENV       – set to "development" to prefer the local fallback
 */

'use strict';

const path  = require('path');
const fs    = require('fs');
const dotenv = require('dotenv');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ---------------------------------------------------------------------------
// Configuration (no secret values here – only structural settings)
// ---------------------------------------------------------------------------

const ENV_FILE   = process.env.ENV_FILE  || '.env.test';
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';
const SM_PREFIX  = process.env.AWS_SM_PREFIX || '';          // e.g. "myapp/prod/"
const IS_DEV     = process.env.NODE_ENV === 'development';

// ---------------------------------------------------------------------------
// Step 1 – Parse the env file to learn which secret names exist.
//          The parsed values live only in this module-level Map and are
//          never written to process.env or exported.
// ---------------------------------------------------------------------------

const envFilePath = path.resolve(process.cwd(), ENV_FILE);

if (!fs.existsSync(envFilePath)) {
  throw new Error(
    `[secrets] Env file not found: ${envFilePath}. ` +
    'Set the ENV_FILE environment variable to the correct path.'
  );
}

const parsed = dotenv.parse(fs.readFileSync(envFilePath));

// The set of secret names this app requires, derived entirely from the file.
const REQUIRED_SECRET_NAMES = Object.freeze(Object.keys(parsed));

// Local fallback store – values come from the env file, never hardcoded here.
const localFallback = new Map(Object.entries(parsed));

