/**
 * secrets.js
 *
 * Centralised secret-loading module.
 *
 * Resolution order for every secret name:
 *   1. AWS Secrets Manager  (always attempted when NODE_ENV !== 'development')
 *   2. Local .env.test file (fallback, or primary source in development)
 *
 * The list of *names* that the application needs is derived by parsing the
 * keys from .env.test — the values in that file are never read or used by
 * this module.
 *
 * Required peer dependencies (add to package.json):
 *   "@aws-sdk/client-secrets-manager": "^3.x"
 *   "dotenv": "^16.x"
 */

'use strict';

const path = require('path');
const fs   = require('fs');

// ---------------------------------------------------------------------------
// 1.  Parse .env.test for SECRET NAMES ONLY (values are deliberately ignored)
// ---------------------------------------------------------------------------

/**
 * Reads an env file and returns an array of the declared key names.
 * Lines that are blank or start with # are skipped.
 * Values are never stored — only the left-hand side of each KEY=... line.
 *
 * @param {string} filePath  Absolute path to the env file.
 * @returns {string[]}       Ordered, deduplicated list of key names.
 */
function parseSecretNames(filePath) {
  if (!fs.existsSync(filePath)) {
    return [];
  }

  const lines = fs.readFileSync(filePath, 'utf8').split(/\r?\n/);
  const names = new Set();

  for (const raw of lines) {
    const line = raw.trim();

    // Skip blanks and comments
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx < 1) continue; // malformed — no key before '='

    const key = line.slice(0, eqIdx).trim();
    if (key) names.add(key);
  }

  return [...names];
}

const ENV_FILE   = path.resolve(__dirname, '.env.test');
const SECRET_NAMES = parseSecretNames(ENV_FILE);

// ---------------------------------------------------------------------------
// 2.  Local fallback: load .env.test values into a private map
//     (only populated when the file exists; used only as a fallback)
// ---------------------------------------------------------------------------

/**
 * Returns a Map<name, value> sourced from the env file.
 * This map is kept module-private; callers access it only through getSecret().
 *
 * @param {string} filePath
 * @returns {Map<string, string>}
 */
function loadLocalSecrets(filePath) {
  const map = new Map();
  if (!fs.existsSync(filePath)) return map;

  // Use dotenv's parser so we get correct handling of quotes, multiline, etc.
  // We import lazily so that the package is optional in pure-AWS deployments.
  let parse;
  try {
    ({ parse } = require('dotenv'));      // dotenv ≥ 16 exports parse directly
  } catch {
    // dotenv unavailable — fall back to a minimal inline parser
    parse = (src) => {
      const result = {};
      for (const line of src.split(/\r?\n/)) {
        const l = line.trim();
        if (!l || l.startsWith('#')) continue;
        const eq = l.indexOf('=');
        if (eq < 1) continue;
        result[l.slice(0, eq).trim()] = l.slice(eq + 1).trim();
      }
      return result;
    };
  }

  const parsed = parse(fs.readFileSync(filePath));
  for (const [k, v] of Object.entries(parsed)) {
    map.set(k, v);
  }
  return map;
}

// Local secrets are kept in module scope but are not exported.
