 * @returns {Promise<Map<string, string>>}
 */
async function validateAllSecrets() {
  const results = new Map();
  for (const name of SECRET_NAMES) {
    // Errors propagate — the caller (app startup) decides how to handle them.
    const value = await getSecret(name);
    results.set(name, value);
  }
  return results;
}

module.exports = { getSecret, getSecretNames, validateAllSecrets };

/**
 * app.js
 *
 * Express application entry point.
 * All secrets are loaded through secrets.js — never from process.env directly
 * or from hardcoded values.
 */

'use strict';

const express = require('express');
const { getSecret, getSecretNames, validateAllSecrets } = require('./secrets');

const app  = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

/**
 * GET /secret-names
 *
 * Returns the list of required secret *names* (not their values) so that
 * operators can verify that all expected secrets are configured.
 */
app.get('/secret-names', (req, res) => {
  res.json({ secrets: getSecretNames() });
});

/**
 * GET /secret/:name
 *
 * Fetches a single secret by name and returns a redacted confirmation.
 * Values are NEVER sent to the client — this endpoint is provided so that
 * application code has a reference pattern for calling getSecret() inside
 * a route handler.
 *
 * In a real application, remove this route and use getSecret() directly
 * inside the service logic that needs the credential.
 */
app.get('/secret/:name', async (req, res) => {
  const { name } = req.params;

  // Only allow names that were declared in .env.test (deny arbitrary lookups).
  if (!getSecretNames().includes(name)) {
    return res.status(404).json({ error: `Unknown secret name: ${name}` });
  }

  try {
    const value = await getSecret(name);
    // Return length + prefix so operators can confirm resolution without
    // exposing the full value in logs or responses.
    res.json({
      name,
      resolved : true,
      preview  : `${value.slice(0, 4)}${'*'.repeat(Math.max(0, value.length - 4))}`,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ---------------------------------------------------------------------------
// Startup: validate all secrets before accepting traffic
// ---------------------------------------------------------------------------

async function start() {
  try {
    console.log('[app] Validating secrets…');
    await validateAllSecrets();
    console.log('[app] All secrets resolved successfully.');
  } catch (err) {
    console.error('[app] Secret validation failed — aborting startup:', err.message);
    process.exit(1);
  }

  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

// Only call start() when this file is run directly (not when required in tests)
if (require.main === module) {
  start();
}

module.exports = app;
